// @ts-check
/** @type {any} */
let currentReportSaleId = null;
/** @type {any} */
let selectedUserSessionsTarget = null;

/** @param {string} section */
function moduleWorkflowItems(section) {
  const facts = workflowFacts();
  const topOverdue = facts.overdue[0];
  const topNearDue = facts.nearDue[0];
  const lowItem = facts.lowStock[0];
  const expiringItem = facts.nearExpiry.sort((a, b) => daysUntil(a.expiry) - daysUntil(b.expiry))[0];
  const missingDocClient = facts.missingDocs[0];
  const pendingContact = facts.pendingContacts[0];
  const pendingTransfer = facts.pendingTransfers[0];
  const duePayable = facts.duePayables[0];
  const topOpenIssue = facts.openIssues[0];
  const topEscalatedIssue = facts.escalatedIssues[0];
  const lowStockRecords = facts.lowStock.map((item) => item.lot).join("|");
  const missingDocRecords = facts.missingDocs.map((client) => client.name).join("|");
  const pendingExpenseRecords = facts.pendingExpenses.map((expense) => expense.id).join("|");
  const duePayableRecords = facts.duePayables.map((payable) => payable.id).join("|");
  const openIssueRecords = facts.openIssues.map((report) => report.id).join("|");
  /** @type {Record<string, any>} */
  const queues = {
    dashboard: [
      topOverdue && { title: "Collect overdue AR", text: `${topOverdue.client} has ${peso.format(topOverdue.net - topOverdue.paid)} open.`, action: `open-ar:${topOverdue.documentNo || topOverdue.id}`, tone: "risk" },
      lowItem && { title: "Prevent stockout", text: `${facts.lowStock.length} low/critical stock record${facts.lowStock.length === 1 ? "" : "s"}.`, action: `open-inventory:${lowStockRecords}`, tone: "warning" },
      missingDocClient && { title: "Complete client docs", text: `${facts.missingDocs.length} client${facts.missingDocs.length === 1 ? "" : "s"} missing required attachments.`, section: "masterlists", record: missingDocRecords, tone: "info" },
      pendingTransfer && { title: "Receive transfer", text: `${pendingTransfer.id} is waiting for ${pendingTransfer.to}.`, section: "inventory", record: pendingTransfer.id, tone: "warning" },
    ],
    analytics: [
      { title: "Prioritize recovery", text: `${facts.overdue.length + facts.nearDue.length} invoices are overdue or near due.`, section: "collections", action: "queue-collections", tone: facts.overdue.length ? "risk" : "warning" },
      expiringItem && { title: "Bundle expiring stock", text: `${expiringItem.item} expires in ${daysUntil(expiringItem.expiry)} days.`, action: `open-inventory:${expiringItem.lot}`, tone: "warning" },
      { title: "Review demand pattern", text: "Use top brands/items to plan reorder and sales focus.", tone: "info" },
    ],
    masterlists: [
      missingDocClient && { title: "Missing client documents", text: `${facts.missingDocs.length} clients need document completion.`, section: "masterlists", record: missingDocRecords, tone: "warning" },
      facts.duplicateClients.length && { title: "Duplicate client/TIN risk", text: `${facts.duplicateClients.length} possible duplicates need Superadmin review.`, section: "masterlists", record: facts.duplicateClients[0].name, tone: "risk" },
      { title: "Standardize client terms", text: "Keep terms on client records so invoices auto-calculate due dates correctly.", tone: "info" },
    ],
    inventory: [
      lowItem && { title: "Reorder or transfer", text: `${facts.lowStock.length} low/critical stock records.`, action: `open-inventory:${lowStockRecords}`, tone: "risk" },
      expiringItem && { title: "FEFO dispatch", text: `Use lot ${expiringItem.lot} first; expires ${expiringItem.expiry}.`, action: `open-inventory:${expiringItem.lot}`, tone: "warning" },
      pendingTransfer && { title: "Receive transfer", text: `${pendingTransfer.id} is waiting for confirmation.`, section: "inventory", record: pendingTransfer.id, tone: "warning" },
    ],
    sales: [
      expiringItem && { title: "Sell FEFO stock first", text: `${expiringItem.item} lot ${expiringItem.lot} should be prioritized.`, action: `open-inventory:${expiringItem.lot}`, tone: "warning" },
      missingDocClient && { title: "Client compliance before invoice", text: `Check ${facts.missingDocs.length} client${facts.missingDocs.length === 1 ? "" : "s"} with missing docs.`, section: "masterlists", record: missingDocRecords, tone: "warning" },
      { title: "Copy repeat orders", text: "Use client history before encoding repeat invoice lines manually.", tone: "info" },
    ],
    invoicing: [
      { title: "Prevent document errors", text: "Duplicate SI/TS/DR, missing lots, expired stock, and credit limits are blocked before save.", tone: "info" },
      topNearDue && { title: "Collect before new exposure", text: `${topNearDue.client} is near due before more credit.`, section: "collections", record: topNearDue.client, tone: "warning" },
    ],
    collections: [
      pendingContact && { title: "Today’s call queue", text: `${facts.pendingContacts.length} clients still need contact outcome.`, section: "collections", record: pendingContact.client, action: "queue-collections", tone: "warning" },
      topOverdue && { title: "Highest AR risk", text: `${topOverdue.client}: ${peso.format(topOverdue.net - topOverdue.paid)} overdue.`, action: `open-ar:${topOverdue.documentNo || topOverdue.id}`, tone: "risk" },
      { title: "Send reminders", text: "Mark all pending follow-ups as reminded in one batch.", section: "collections", action: "bulk-remind", tone: "info" },
    ],
    "receivables-tracker": [
      topOverdue && { title: "Open oldest overdue", text: `${topOverdue.documentNo || topOverdue.id} needs collection action.`, action: `open-ar:${topOverdue.documentNo || topOverdue.id}`, tone: "risk" },
      { title: "View aging buckets", text: "Use AR status tabs to reduce manual filtering.", tone: "info" },
    ],
    warranty: [
      data.warranties[0] && { title: "Schedule service", text: "Use serial warranty records before dispatching replacement units.", action: `open-warranty:${data.warranties[0].serial}`, tone: "info" },
    ],
    "product-issues": [
      topOpenIssue && { title: "Work open reports", text: `${facts.openIssues.length} open report${facts.openIssues.length === 1 ? "" : "s"}, oldest: ${topOpenIssue.companyName}.`, action: `open-issue:${openIssueRecords}`, tone: "risk" },
      topEscalatedIssue && { title: "Engineering follow-up", text: `${facts.escalatedIssues.length} report${facts.escalatedIssues.length === 1 ? "" : "s"} passed to Engineering awaiting resolution.`, action: `open-issue:${topEscalatedIssue.id}`, tone: "warning" },
      { title: "Complete QC parameters", text: "Fill in all QC parameters and actions taken before marking a report Resolved.", tone: "info" },
    ],
    "purchase-history": [
      { title: "Repeat-order shortcut", text: "Review client history before creating manual invoice lines.", tone: "info" },
    ],
    payables: [
      duePayable && { title: "Payable queue", text: `${facts.duePayables.length} payable${facts.duePayables.length === 1 ? "" : "s"} have open balances.`, action: `open-payable:${duePayableRecords}`, tone: "warning" },
      { title: "Cheque controls", text: "Cheque payables require bank and cheque number before save.", tone: "info" },
    ],
    replenishments: [
      facts.pendingExpenses.length && { title: "Approval queue", text: `${facts.pendingExpenses.length} expenses need HR/accounting action.`, section: "replenishments", record: pendingExpenseRecords, tone: "warning" },
    ],
    imports: [
      { title: "Pre-import safety", text: "Duplicate clients, unsupported areas, and missing fields are blocked before import.", section: "imports", action: "check-import", tone: "info" },
    ],
    reports: [
      { title: "Scheduled reporting", text: "Use saved report cards to avoid rebuilding common management views.", tone: "info" },
      facts.overdue.length && { title: "Export AR support", text: `${facts.overdue.length} overdue invoices should be included in collection report.`, action: `open-ar:${topOverdue.documentNo || topOverdue.id}`, tone: "risk" },
    ],
    reconciliation: [
      { title: "Run fix-oriented checks", text: "Find duplicate receipts, missing docs, transfer issues, and AR mismatches with direct fix buttons.", action: "run-reconciliation", actionLabel: "Run", tone: "info" },
      facts.chequeReviews.length && { title: "Cheque data gap", text: `${facts.chequeReviews.length} cheque records need bank/date cleanup.`, section: "collections", tone: "warning" },
    ],
    security: [
      { title: "Audit risky actions", text: "Watch discount approvals, credit overrides, cancellations, and backdated payments.", tone: "info" },
    ],
    notifications: [
      { title: "Actionable alerts", text: "Open each alert directly instead of searching module tables.", tone: "info" },
    ],
    users: [
      { title: "Role-based queues", text: "Keep each user focused on modules and approvals for their role.", tone: "info" },
    ],
  };
  return (queues[section] || []).filter(Boolean).slice(0, 4);
}

/** @param {string} section */
function workflowTitle(section) {
  return ({ dashboard: "Smart Action Queue", analytics: "Decision Shortcuts", masterlists: "Data Quality Queue", inventory: "Warehouse Task Queue", sales: "Sales Safety Queue", invoicing: "Invoice Error Prevention", collections: "Collector Work Queue", "receivables-tracker": "AR Recovery Queue", payables: "Payables Work Queue", replenishments: "Approval Work Queue", reports: "Report Automation", reconciliation: "Fix Queue", security: "Risk Controls", imports: "Import Safety", warranty: "Service Queue", "purchase-history": "Repeat Order Assist", notifications: "Alert Workflow", users: "Access Workflow", "product-issues": "Support Resolution Queue" }[section] || "Workflow Assistant");
}

/** @param {string} sectionId */
function ensureWorkflowPanel(sectionId) {
  if (sectionId === "notifications") return null;
  const section = document.getElementById(sectionId);
  if (!section || qsIn(section, ".workflow-assist")) return section?.querySelector(".workflow-assist");
  const anchor = qsIn(section, ".section-header, .ui-tabs, .toolbar, .feature-strip") || section.firstElementChild;
  const panel = document.createElement("article");
  panel.className = "panel workflow-assist";
  panel.dataset.workflowSection = sectionId;
  panel.innerHTML = `<div class="panel-header"><div><p class="eyebrow">Workflow Assistant</p><h2></h2><p></p></div><span class="badge"></span></div><div class="workflow-grid"></div>`;
  // Redesigned pages (.ui-tabs): the assistant sits under the tab row, below the page header.
  anchor?.insertAdjacentElement(anchor.classList.contains("section-header") || anchor.classList.contains("ui-tabs") ? "afterend" : "beforebegin", panel);
  return panel;
}

/** @param {string} sectionId */
function renderWorkflowAssist(sectionId) {
  const panel = ensureWorkflowPanel(sectionId);
  if (!panel) return;
  const items = moduleWorkflowItems(sectionId);
  qsIn(panel, "h2").textContent = workflowTitle(sectionId);
  qsIn(panel, "p:not(.eyebrow)").textContent = "Recommended next actions to reduce manual work, prevent errors, and finish recurring tasks faster.";
  qsIn(panel, ".badge").textContent = `${items.length} recommendation${items.length === 1 ? "" : "s"}`;
  const slim = sectionId === "inventory" && !items.length;
  panel.classList.toggle("is-clear", slim);
  if (slim) {
    qsIn(panel, "h2").textContent = "Warehouse task queue is clear.";
    qsIn(panel, "p:not(.eyebrow)").textContent = "No urgent recommendations for Inventory right now.";
  }
  qsIn(panel, ".workflow-grid").innerHTML = items.map(workflowCard).join("") || `<article class="workflow-card success"><div><strong>All clear</strong><span>No urgent workflow recommendations for this module.</span></div></article>`;
}

const WORKFLOW_ASSIST_SECTIONS = ["dashboard", "masterlists", "warranty", "imports", "reports", "reconciliation", "security", "users", "product-issues"];

function renderWorkflowAssistAll() {
  WORKFLOW_ASSIST_SECTIONS.forEach(renderWorkflowAssist);
  Object.keys(WORKFLOW_RULES).forEach(renderModuleAssistant);
}

// ===== Workflow assistant (redesigned modules) =====================================================
// Every recommendation on a redesigned page comes from a rule below: one place to add, drop or
// re-word them. A rule returns null when it doesn't apply, or { text, action, attrs, tone, money }.
// `attrs` must be data-* attributes an existing click handler understands (the assistant renders
// inside the module's <section>, so module-scoped handlers such as data-inventory-filter work).
// Recommendations are ranked by tone (red → green), then by money at stake.
/** @typedef {{ id: string, rule: (ctx: WorkflowRuleContext) => UiRec | null }} WorkflowRule */
/** Shared, lazily computed inputs (each is built at most once per assistant render). @typedef {{ readonly cover: StockCoverRow[], readonly lots: { row: StockRow, status: string }[], readonly receipts: CollectionReceipt[], readonly receivables: ReturnType<typeof receivablesByClient> }} WorkflowRuleContext */

/** @type {Record<string, boolean>} */
const workflowAssistantOpen = {};
const WORKFLOW_TONE_RANK = ["red", "orange", "amber", "blue", "slate", "accent", "green"];
const plural = (/** @type {number} */ n, /** @type {string} */ word, /** @type {string} */ many = `${word}s`) => `${n} ${n === 1 ? word : many}`;

/** @type {Record<string, WorkflowRule[]>} */
const WORKFLOW_RULES = {
  logs: [
    { id: "failed-sign-ins", rule: () => {
      const s = auditSummaryState.data;
      const group = s ? auditFailedByAccount(s).find((entry) => entry.list.length >= 3) : undefined;
      return group ? { tone: "red", text: `Possible password guessing: ${group.list.length} failed sign-ins on ${group.account} this week.`, action: "Sign-ins", attrs: { "data-wa-goto": "logs|signins|failed|" } } : null;
    } },
    { id: "after-hours-exports", rule: () => {
      const late = (auditSummaryState.data?.afterHours || []).filter((entry) => entry.sensitive === "Export");
      return late.length ? { tone: "orange", text: late.length === 1 ? `${late[0].user} exported data at ${auditWhen(late[0]).split(" · ")[1]} (${String(late[0].record || late[0].action).slice(0, 60)}).` : `${plural(late.length, "export")} made after hours this week.`, action: "Review", attrs: { "data-wa-goto": "logs|sensitive|Export|" } } : null;
    } },
    { id: "stock-without-reason", rule: () => {
      const s = auditSummaryState.data;
      const list = s ? auditStockWithoutReason(s) : [];
      return list.length ? { tone: "amber", text: `${plural(list.length, "stock adjustment")} this week gave no reason.`, action: "Review", attrs: { "data-wa-goto": "logs|sensitive|Money or stock|" } } : null;
    } },
  ],
  analytics: [
    { id: "hold-orders", rule: (ctx) => {
      const risky = new Map(ctx.receivables.filter((entry) => entry.amounts[3] + entry.amounts[4] > 0.005 || entry.bounced.length).map((entry) => [entry.client, entry]));
      const orders = salesOpenOrders().filter((po) => risky.has(po.client));
      if (!orders.length) return null;
      const first = orders[0];
      const target = canViewModule("purchase-history") ? `purchase-history|profile||${first.client}` : "receivables-tracker|aging|risk|";
      return { tone: "red", money: orders.reduce((sum, po) => sum + salesOrderTotal(po), 0), text: orders.length === 1 ? `${first.client} has an open order (${first.id}) while ${salesPesoShort(risky.get(first.client)?.overdue || 0)} is over 60 days overdue.` : `${plural(new Set(orders.map((po) => po.client)).size, "client")} with invoices over 60 days overdue still have open orders.`, action: "Open client", attrs: { "data-wa-goto": target } };
    } },
    { id: "collections-behind", rule: () => {
      const facts = bizFacts();
      const gross = facts.monthGross.slice(8, 11).reduce((a, b) => a + b, 0), got = facts.monthCollected.slice(8, 11).reduce((a, b) => a + b, 0);
      if (!(gross > 0) || got >= gross * 0.85) return null;
      return { tone: "amber", money: gross - got, text: `Collections were ${Math.round((1 - got / gross) * 100)}% below invoicing over the last 3 full months (${salesPesoShort(gross - got)}).`, action: "Receivables", attrs: { "data-wa-goto": "receivables-tracker|aging|risk|" } };
    } },
    { id: "products-running-out", rule: ({ cover }) => {
      if (!canSeeMargins()) return null;
      const short = cover.filter((row) => row.months !== null && row.months < 1 && row.onOrder <= 0);
      return short.length ? { tone: "orange", text: `${plural(short.length, "product")} will run out within a month and ${short.length === 1 ? "is" : "are"} not on order.`, action: "Show", attrs: { "data-wa-goto": "analytics|products|short|" } } : null;
    } },
  ],
  "purchase-history": [
    { id: "risk-with-orders", rule: (ctx) => {
      const risky = new Map(ctx.receivables.filter((entry) => entry.amounts[3] + entry.amounts[4] > 0.005 || entry.bounced.length).map((entry) => [entry.client, entry]));
      const order = salesOpenOrders().find((po) => risky.has(po.client));
      return order ? { tone: "red", money: salesOrderTotal(order), text: `${order.client}: ${order.id} is still open while older invoices are over 60 days overdue.`, action: "Open client", attrs: { "data-wa-goto": `purchase-history|profile||${order.client}` } } : null;
    } },
    { id: "slipping-clients", rule: () => {
      const facts = bizFacts();
      const down = clientSummaries(facts).filter((s) => s.trend !== null && s.trend <= -25 && s.rev12 > 0);
      if (!down.length) return null;
      return { tone: "orange", money: down.reduce((sum, s) => sum + ((s.biz?.revPrev || 0) - s.rev12), 0), text: `${plural(down.length, "client")} bought at least 25% less than the year before${down.length <= 2 ? `: ${down.map((s) => s.name).join(", ")}` : ""}.`, action: "Show", attrs: { "data-wa-goto": "purchase-history|clients|slipping-risk|" } };
    } },
  ],
  inventory: [
    { id: "expired-on-hand", rule: (ctx) => {
      if (isDemoOnlyRole()) return null;
      // Same count as the Expired card on the Stocks tab.
      const lots = ctx.lots.filter((lot) => lot.status === "Expired").map((lot) => lot.row);
      if (!lots.length) return null;
      const units = lots.reduce((sum, row) => sum + Math.max(0, Number(row.qty || 0)), 0);
      return { tone: "red", text: `${plural(lots.length, "expired lot")} (${units.toLocaleString("en-PH")} units) — pull them for disposal.`, action: "Show expired", attrs: { "data-inventory-filter": "disposal" } };
    } },
    { id: "critical-stock", rule: (ctx) => {
      if (isDemoOnlyRole()) return null;
      const lots = ctx.lots.filter((lot) => lot.status === "Critical");
      return lots.length ? { tone: "red", text: `${plural(lots.length, "stock record")} at a critical level.`, action: "Show critical", attrs: { "data-inventory-filter": "critical" } } : null;
    } },
    { id: "receipts-to-approve", rule: () => {
      if (!canApproveStockReceipts()) return null;
      const n = (data.stockReceipts || []).filter((receipt) => receipt.status === "Pending Approval").length;
      return n ? { tone: "amber", text: `${plural(n, "stock receipt")} waiting for your approval.`, action: "Review", attrs: { "data-inventory-workflow": "receipts" } } : null;
    } },
    { id: "transfers-to-dispatch", rule: () => {
      if (!canApproveInventoryChanges()) return null;
      const n = (data.pendingTransfers || []).filter((transfer) => transfer.status === "For Receiving").length;
      return n ? { tone: "amber", text: `${plural(n, "transfer")} waiting to be dispatched.`, action: "Open transfers", attrs: { "data-inventory-workflow": "transfers" } } : null;
    } },
    { id: "transfers-in-transit", rule: () => {
      if (isDemoOnlyRole()) return null;
      const n = (data.pendingTransfers || []).filter((transfer) => ["In Transit", "Incomplete"].includes(transfer.status)).length;
      return n ? { tone: "blue", text: `${plural(n, "transfer")} in transit — confirm when received.`, action: "Open transfers", attrs: { "data-inventory-workflow": "transfers" } } : null;
    } },
    { id: "under-one-month-no-order", rule: ({ cover }) => {
      if (isDemoOnlyRole()) return null;
      const short = cover.filter((row) => row.months !== null && row.months < 1 && row.onOrder <= 0).sort((a, b) => /** @type {number} */ (a.months) - /** @type {number} */ (b.months));
      if (!short.length) return null;
      const first = short[0];
      const canOrder = canEditModule("inventory");
      return {
        tone: "orange",
        text: `${plural(short.length, "item")} under 1 month of cover with nothing on order — ${first.name} has ${first.months === 0 ? "none left" : `${/** @type {number} */ (first.months).toFixed(1)} months left`}.`,
        action: canOrder ? "New PO" : "Show item",
        attrs: canOrder ? { "data-action": "open-modal", "data-type": "inventoryPurchaseOrder" } : { "data-workflow-action": `open-inventory:${first.code}` },
      };
    } },
    { id: "low-stock", rule: (ctx) => {
      if (isDemoOnlyRole()) return null;
      const lots = ctx.lots.filter((lot) => lot.status === "Low Stock");
      return lots.length ? { tone: "orange", text: `${plural(lots.length, "stock record")} below the minimum level.`, action: "Show low stock", attrs: { "data-inventory-filter": "low" } } : null;
    } },
    { id: "pos-to-receive", rule: () => {
      if (!canManagePoReceiving()) return null;
      const n = receivingPurchaseOrders().filter((po) => ["For Receiving", "Partially Received"].includes(po.status)).length;
      return n ? { tone: "blue", text: `${plural(n, "purchase order")} ready to receive.`, action: "Receive", attrs: { "data-inventory-workflow": "receiving" } } : null;
    } },
    { id: "near-expiry-fefo", rule: (ctx) => {
      if (isDemoOnlyRole()) return null;
      const lots = ctx.lots.filter((lot) => lot.status === "Near Expiry");
      return lots.length ? { tone: "amber", text: `${plural(lots.length, "lot")} near expiry — dispatch these first (FEFO).`, action: "Show near expiry", attrs: { "data-inventory-filter": "near" } } : null;
    } },
  ],
  sales: [
    { id: "bounced-client-open-order", rule: () => {
      const openOrders = salesOpenOrders();
      const bounced = data.payments.filter((payment) => payment.collectionStatus === "Bounced" && !payment.voided && openOrders.some((po) => po.client === payment.client));
      if (!bounced.length) return null;
      const clients = [...new Set(bounced.map((payment) => payment.client))];
      const order = openOrders.find((po) => po.client === clients[0]);
      const money = bounced.reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
      return { tone: "red", money, text: `${clients.length === 1 ? clients[0] : plural(clients.length, "client")} ${clients.length === 1 ? "has" : "have"} an open order while a bounced check (${salesPesoShort(money)}) is not yet replaced.`, action: "Open order", attrs: { "data-wa-goto": `sales|orders||${order?.id || ""}` } };
    } },
    { id: "orders-waiting-to-invoice", rule: () => {
      const waiting = salesOpenOrders().filter((po) => poStatus(po) === "For Invoicing" && daysUntil(po.date) <= -2);
      if (!waiting.length) return null;
      const money = waiting.reduce((sum, po) => sum + salesOrderTotal(po), 0);
      const oldest = waiting.reduce((a, b) => (String(a.date) <= String(b.date) ? a : b));
      return { tone: "orange", money, text: `${plural(waiting.length, "order")} (${salesPesoShort(money)}) waiting 2+ days with nothing invoiced — oldest ${oldest.id}, ${-daysUntil(oldest.date)} days.`, action: "Show orders", attrs: { "data-wa-goto": "sales|orders|For Invoicing|" } };
    } },
    { id: "orders-partly-invoiced", rule: () => {
      const partial = salesOpenOrders().filter((po) => poStatus(po) === "Pending Orders");
      if (!partial.length) return null;
      return { tone: "amber", text: `${plural(partial.length, "order")} partly invoiced — the remaining lines still need an invoice or DR.`, action: "Show orders", attrs: { "data-wa-goto": "sales|orders|Pending Orders|" } };
    } },
    { id: "not-delivered", rule: () => {
      const docs = salesScopedDocuments().filter((sale) => sale.status !== "Cancelled" && (sale.deliveryStatus || "Pending") === "Pending" && daysUntil(sale.date) <= -3);
      if (!docs.length) return null;
      return { tone: "amber", text: `${plural(docs.length, "document")} still marked Pending delivery 3+ days after issue.`, action: "Show deliveries", attrs: { "data-wa-goto": "sales|deliveries|Pending|" } };
    } },
    { id: "no-signed-copy", rule: () => {
      const docs = salesScopedDocuments().filter((sale) => sale.status !== "Cancelled" && sale.deliveryStatus === "Document Delivered" && daysUntil(sale.date) <= -7);
      if (!docs.length) return null;
      return { tone: "blue", text: `${plural(docs.length, "delivered document")} with no signed copy back after 7+ days.`, action: "Show deliveries", attrs: { "data-wa-goto": "sales|deliveries|Document Delivered|" } };
    } },
    { id: "missing-client-docs", rule: () => {
      if (!canViewModule("masterlists")) return null;
      const clients = [...new Set(salesOpenOrders().map((po) => po.client))].map((name) => data.clients.find((client) => client.name === name)).filter((client) => client && requiredClientDocs.some((doc) => !client.docs?.includes(doc)));
      if (!clients.length) return null;
      return { tone: "amber", text: `${plural(clients.length, "client")} with open orders ${clients.length === 1 ? "is" : "are"} missing required documents — check before invoicing.`, action: "Open masterlist", attrs: { "data-go-section": "masterlists", "data-focus-record": clients.map((client) => client?.name).join("|") } };
    } },
    { id: "sell-near-expiry-first", rule: (ctx) => {
      const inView = new Set(byBranch(data.inventory));
      const lots = ctx.lots.filter((lot) => lot.status === "Near Expiry" && inView.has(lot.row)).map((lot) => lot.row);
      if (!lots.length) return null;
      const names = lots.slice(0, 2).map((row) => row.item).join(", ");
      const canOpen = canViewModule("inventory") && !isDemoOnlyRole();
      return { tone: "amber", text: `Sell first: ${plural(lots.length, "lot")} near expiry (${names}${lots.length > 2 ? ", …" : ""}).`, action: canOpen ? "Show lots" : "", attrs: canOpen ? { "data-workflow-action": "inventory-status:near" } : {} };
    } },
  ],
  invoicing: [
    { id: "overdue-invoices", rule: () => {
      const overdue = byBranch(data.sales, "area").filter((sale) => invoicingStatus(sale) === "Overdue");
      if (!overdue.length) return null;
      const money = overdue.reduce((sum, sale) => sum + salesBalance(sale), 0);
      const clients = new Set(overdue.map((sale) => sale.client)).size;
      return { tone: "red", money, text: `${plural(overdue.length, "invoice")} overdue (${salesPesoShort(money)}) across ${plural(clients, "client")} — they're due a statement of account.`, action: "Show overdue", attrs: { "data-wa-goto": "invoicing|invoices|Overdue|" } };
    } },
    { id: "credit-approvals", rule: () => {
      if (!canApproveCreditInvoice()) return null;
      const waiting = (data.pendingCreditInvoices || []).filter((request) => request.status === "Pending");
      if (!waiting.length) return null;
      return { tone: "amber", text: `${plural(waiting.length, "over-limit invoice")} waiting for your credit approval.`, action: "Review", attrs: { "data-wa-goto": `invoicing|credit|Pending|${waiting.length === 1 ? waiting[0].id : ""}` } };
    } },
    { id: "due-this-week", rule: () => {
      const soon = byBranch(data.sales, "area").filter((sale) => ["SI", "TS"].includes(documentType(sale.type)) && sale.status !== "Cancelled" && salesBalance(sale) > 0.005 && daysUntil(salesDueDate(sale)) >= 0 && daysUntil(salesDueDate(sale)) <= 7);
      if (!soon.length) return null;
      const money = soon.reduce((sum, sale) => sum + salesBalance(sale), 0);
      return { tone: "blue", money, text: `${plural(soon.length, "invoice")} (${salesPesoShort(money)}) fall due within 7 days — remind those clients before adding more credit.`, action: "Show", attrs: { "data-wa-goto": "invoicing|invoices|duesoon|" } };
    } },
  ],
  collections: [
    { id: "bounced-not-replaced", rule: (ctx) => {
      const bounced = ctx.receipts.filter((receipt) => receipt.state === "bounced");
      if (!bounced.length) return null;
      const money = bounced.reduce((sum, receipt) => sum + receipt.total, 0);
      const first = bounced[0];
      return { tone: "red", money, text: bounced.length === 1 ? `${first.client}'s bounced check (${salesPesoShort(money)}) still needs a replacement.` : `${plural(bounced.length, "bounced check")} (${salesPesoShort(money)}) still need a replacement.`, action: "Show bounced", attrs: { "data-wa-goto": `collections|receipts|bounced|${bounced.length === 1 ? first.id : ""}` } };
    } },
    { id: "to-deposit", rule: (ctx) => {
      const waiting = ctx.receipts.filter((receipt) => receipt.state === "deposit");
      if (!waiting.length) return null;
      const cash = waiting.filter((receipt) => collectionMethodKey(receipt.method) === "cash").reduce((sum, receipt) => sum + receipt.total, 0);
      const money = waiting.reduce((sum, receipt) => sum + receipt.total, 0);
      return { tone: "amber", money, text: `${salesPesoShort(money)} waiting to be deposited${cash > 0.005 ? ` (${salesPesoShort(cash)} in cash)` : ""} — ${plural(waiting.length, "receipt")}.`, action: "Deposit slips", attrs: { "data-wa-goto": "collections|deposits||" } };
    } },
    { id: "pdc-now-due", rule: () => {
      const due = data.payments.filter((payment) => !payment.voided && payment.collectionStatus === "Posted Date" && (payment.postedDate || payment.chequeDate) && daysUntil(payment.postedDate || payment.chequeDate) <= 0);
      if (!due.length) return null;
      const money = due.reduce((sum, payment) => sum + Number(payment.amount || 0), 0);
      return { tone: "amber", money, text: `${plural(due.length, "post-dated check")} (${salesPesoShort(money)}) ${due.length === 1 ? "is" : "are"} now dated today or earlier — deposit ${due.length === 1 ? "it" : "them"}.`, action: "Show checks", attrs: { "data-wa-goto": "collections|register|pdc|" } };
    } },
    { id: "collection-receipts-to-approve", rule: (ctx) => {
      if (!canApprovePaymentRequests()) return null;
      const waiting = ctx.receipts.filter((receipt) => receipt.state === "approval");
      if (!waiting.length) return null;
      return { tone: "slate", money: waiting.reduce((sum, receipt) => sum + receipt.total, 0), text: `${plural(waiting.length, "collection receipt")} waiting for your approval.`, action: "Review", attrs: { "data-wa-goto": "collections|receipts|approval|" } };
    } },
  ],
  "receivables-tracker": [
    { id: "at-risk-clients", rule: (ctx) => {
      const risky = ctx.receivables.filter((entry) => entry.risk === "risk").sort((a, b) => b.overdue - a.overdue);
      if (!risky.length) return null;
      const money = risky.reduce((sum, entry) => sum + entry.overdue, 0);
      const first = risky[0];
      const why = first.bounced.length && first.amounts[4] > 0.005 ? "over 90 days overdue and has a bounced check" : first.bounced.length ? "has a bounced check" : "over 90 days overdue";
      return { tone: "red", money, text: risky.length === 1 ? `${first.client} is ${why}.` : `${plural(risky.length, "client")} at risk (${salesPesoShort(money)} overdue) — ${first.client} is ${why}.`, action: "Open", attrs: { "data-wa-goto": `receivables-tracker|aging|risk|${risky.length === 1 ? first.client : ""}` } };
    } },
    { id: "due-for-statement", rule: (ctx) => {
      const due = ctx.receivables.filter((entry) => entry.overdue > 0.005).sort((a, b) => b.overdue - a.overdue);
      if (!due.length) return null;
      const names = due.slice(0, 3).map((entry) => entry.client).join(", ");
      return { tone: "amber", money: due.reduce((sum, entry) => sum + entry.overdue, 0), text: `${plural(due.length, "client")} due a statement of account: ${names}${due.length > 3 ? ` and ${due.length - 3} more` : ""}.`, action: "Statements", attrs: { "data-wa-goto": "receivables-tracker|soa|overdue|" } };
    } },
    { id: "follow-ups-needed", rule: () => {
      // Same test as the Follow-ups tab's "Need a follow-up" card.
      const canViewAll = ["Accounting", "Admin", "Superadmin", "CEO"].includes(currentUser?.role);
      const n = (data.collectionContacts || []).filter((contact) => (canViewAll || isClientAssignedToCurrentUser(contact.client)) && ["Pending", "No Response", "Unreached", "Called"].includes(String(contact.status || "Pending"))).length;
      return n ? { tone: "amber", text: `${plural(n, "client")} still need a follow-up call this week.`, action: "Follow-ups", attrs: { "data-wa-goto": "receivables-tracker|followups|needs|" } } : null;
    } },
    { id: "cheques-to-pick-up", rule: () => {
      const n = (data.collectionContacts || []).filter((contact) => contact.status === "Cheque Available").length;
      return n ? { tone: "blue", text: `${plural(n, "client")} ${n === 1 ? "has a check" : "have checks"} ready for pickup.`, action: "Show", attrs: { "data-wa-goto": "receivables-tracker|followups|Cheque Available|" } } : null;
    } },
  ],
  "purchase-orders": [
    { id: "pos-to-approve", rule: () => {
      if (!canApprovePurchaseOrders()) return null;
      const waiting = (data.inventoryPurchaseOrders || []).filter((po) => po.status === "Pending Approval");
      if (!waiting.length) return null;
      const money = waiting.reduce((sum, po) => sum + inventoryPoTotal(po), 0);
      const top = [...waiting].sort((a, b) => inventoryPoTotal(b) - inventoryPoTotal(a))[0];
      return { tone: "amber", money, text: waiting.length === 1 ? `${top.id} (${salesPesoShort(money)}) is waiting for your approval.` : `${plural(waiting.length, "purchase order")} (${salesPesoShort(money)}) are waiting for your approval.`, action: "Review", attrs: { "data-wa-goto": `purchase-orders|pos|approval|${waiting.length === 1 ? top.id : ""}` } };
    } },
    { id: "not-on-order", rule: (ctx) => {
      const none = supplierReorderRows(ctx.cover, supplierPoFactsAll()).filter((row) => row.state.key === "none");
      if (!none.length) return null;
      return { tone: "red", money: none.reduce((sum, row) => sum + row.suggest * row.cost, 0), text: `${none.slice(0, 2).map((row) => row.name).join(" and ")}${none.length > 2 ? ` and ${none.length - 2} more` : ""} ${none.length === 1 ? "is" : "are"} running out and not on any order.`, action: "Reorder", attrs: { "data-wa-goto": "purchase-orders|reorder|none|" } };
    } },
    { id: "late-deliveries", rule: () => {
      const late = supplierPoFactsAll().filter((fact) => fact.lateOpenDays > 0);
      if (!late.length) return null;
      return { tone: "orange", money: late.reduce((sum, fact) => sum + fact.total, 0), text: late.length === 1 ? `${late[0].po.id} from ${late[0].po.supplier} is ${plural(late[0].lateOpenDays, "day")} past its promised date.` : `${plural(late.length, "purchase order")} are past the supplier's promised date.`, action: "Show", attrs: { "data-wa-goto": `purchase-orders|pos|late|${late.length === 1 ? late[0].po.id : ""}` } };
    } },
    { id: "arrived-to-receive", rule: () => {
      if (!canManagePoReceiving()) return null;
      const arrived = (data.inventoryPurchaseOrders || []).filter((po) => po.status === "For Receiving");
      return arrived.length ? { tone: "blue", text: `${plural(arrived.length, "purchase order")} arrived and ${arrived.length === 1 ? "needs" : "need"} receiving.`, action: "Show", attrs: { "data-wa-goto": "purchase-orders|pos|open|" } } : null;
    } },
  ],
  payables: [
    { id: "overdue-bills", rule: () => {
      const late = payableFactsAll().filter((fact) => fact.overdue);
      if (!late.length) return null;
      const money = late.reduce((sum, fact) => sum + fact.balance, 0);
      return { tone: "red", money, text: `${plural(late.length, "bill")} (${salesPesoShort(money)}) ${late.length === 1 ? "is" : "are"} past due.`, action: "Show overdue", attrs: { "data-wa-goto": "payables|bills|overdue|" } };
    } },
    { id: "bills-to-approve", rule: () => {
      if (!canApproveFinancialRequest("payable")) return null;
      const waiting = payableFactsAll().filter((fact) => fact.state === "approval");
      if (!waiting.length) return null;
      const money = waiting.reduce((sum, fact) => sum + Number(fact.p.amount || 0), 0);
      return { tone: "amber", money, text: `${plural(waiting.length, "payable request")} (${salesPesoShort(money)}) waiting for your approval.`, action: "Review", attrs: { "data-wa-goto": "payables|bills|approval|" } };
    } },
    { id: "due-this-week", rule: () => {
      const soon = payableFactsAll().filter((fact) => fact.balance > 0.005 && fact.days >= 0 && fact.days <= 7);
      if (!soon.length) return null;
      const money = soon.reduce((sum, fact) => sum + fact.balance, 0);
      return { tone: "amber", money, text: `${plural(soon.length, "bill")} (${salesPesoShort(money)}) fall due within 7 days and are not approved yet.`, action: "Show", attrs: { "data-wa-goto": "payables|bills|approval|" } };
    } },
  ],
  replenishments: [
    { id: "over-budget", rule: () => {
      const budgets = expenseBudgetMap();
      const now = expenseSpendByCategory(byBranch(data.replenishments, "office"), recentMonthKeys(1)[0]);
      const over = Object.keys(budgets).filter((cat) => (now[cat] || 0) > budgets[cat] * 1.1);
      if (!over.length) return null;
      return { tone: "red", money: over.reduce((sum, cat) => sum + (now[cat] || 0) - budgets[cat], 0), text: `${over.slice(0, 2).join(" and ")}${over.length > 2 ? ` and ${over.length - 2} more` : ""} ${over.length === 1 ? "is" : "are"} more than 10% over this month's budget.`, action: "Budgets", attrs: { "data-wa-goto": "replenishments|budgets|over|" } };
    } },
    { id: "expenses-to-approve", rule: () => {
      if (!canApproveFinancialRequest("expense")) return null;
      const waiting = byBranch(data.replenishments, "office").filter((r) => expenseState(r) === "approval");
      if (!waiting.length) return null;
      const money = waiting.reduce((sum, r) => sum + Number(r.amount || 0), 0);
      return { tone: "amber", money, text: `${plural(waiting.length, "expense request")} (${salesPesoShort(money)}) waiting for approval.`, action: "Review", attrs: { "data-wa-goto": "replenishments|list|approval|" } };
    } },
    { id: "returned-to-me", rule: () => {
      const mine = (data.replenishments || []).filter((r) => expenseState(r) === "returned" && r.createdByUser && r.createdByUser === currentUser?.email);
      return mine.length ? { tone: "orange", text: `${plural(mine.length, "of your expense requests", "of your expense requests")} ${mine.length === 1 ? "was" : "were"} returned for changes.`, action: "Show", attrs: { "data-wa-goto": `replenishments|list|returned|${mine.length === 1 ? mine[0].id : ""}` } } : null;
    } },
    { id: "expenses-no-method", rule: () => {
      const topay = byBranch(data.replenishments, "office").filter((r) => expenseState(r) === "topay");
      if (!topay.length) return null;
      return { tone: "slate", text: `${plural(topay.length, "approved expense")} ${topay.length === 1 ? "has" : "have"} no payment method recorded. Approved expenses count as paid.`, action: "Show", attrs: { "data-wa-goto": "replenishments|list|topay|" } };
    } },
  ],
};

/** Opens a redesigned module on a tab with a status filter and/or a selected record (assistant links). @param {string} module @param {string} tab @param {string} scope @param {string} sel */
function workflowGoto(module, tab, scope, sel) {
  const view = uiBlankViewState();
  view.scope = scope || "";
  view.sel = sel || "";
  if (module === "sales") { if (SALES_TAB_LABELS[tab]) salesTab = tab; salesView = view; salesDocType = "all"; }
  else if (module === "invoicing") { if (INVOICING_TAB_LABELS[tab]) invoicingTab = tab; invoicingView = view; }
  else if (module === "collections") { if (COLLECTIONS_TAB_LABELS[tab]) collectionsTab = tab; collectionsView = view; }
  else if (module === "receivables-tracker") { if (RECEIVABLES_TAB_LABELS[tab]) receivablesTab = tab; receivablesView = view; }
  else if (module === "purchase-orders") { if (PURCHASING_TAB_LABELS[tab]) purchasingTab = tab; purchasingView = view; }
  else if (module === "payables") { if (PAYABLES_TAB_LABELS[tab]) payablesTab = tab; payablesView = view; }
  else if (module === "replenishments") { if (EXPENSES_TAB_LABELS[tab]) expensesTab = tab; expensesView = view; }
  else if (module === "logs") { if (LOGS_TAB_LABELS[tab]) logsTab = tab; logsView = view; }
  else if (module === "analytics") { if (ANALYTICS_TAB_LABELS[tab]) analyticsTab = tab; analyticsView = view; }
  else if (module === "purchase-history") {
    if (CLIENT_HISTORY_TAB_LABELS[tab]) clientHistoryPageTab = tab;
    if (clientHistoryPageTab === "profile") { if (sel) clientHistoryClient = sel; view.sel = ""; }
    clientHistoryView = view;
  }
  else return;
  if (document.body.dataset.activeSection !== module) showSection(module);
  else renderSection(module);
  document.getElementById(`${module === "receivables-tracker" ? "receivables" : module}-tab-panel`)?.scrollIntoView({ block: "start", behavior: "smooth" });
}

/** @param {string} module @returns {UiRec[]} */
function workflowRecommendations(module) {
  const rules = WORKFLOW_RULES[module] || [];
  if (!rules.length) return [];
  /** @type {Record<string, unknown>} */
  const memo = {};
  /** @template T @param {string} key @param {() => T} build @returns {T} */
  const lazy = (key, build) => /** @type {T} */ (memo[key] ??= build());
  /** @type {WorkflowRuleContext} */
  const ctx = {
    get lots() { return lazy("lots", () => data.inventory.map((row) => ({ row, status: inventoryStatus(row) }))); },
    get cover() { return lazy("cover", () => itemStockCover(new Map(ctx.lots.map((lot) => [lot.row, lot.status])))); },
    get receipts() { return lazy("receipts", collectionReceipts); },
    get receivables() { return lazy("receivables", receivablesByClient); },
  };
  /** @type {UiRec[]} */
  const recs = [];
  for (const { rule } of rules) {
    try { const rec = rule(ctx); if (rec) recs.push(rec); } catch (error) { console.warn("Workflow rule failed", error); }
  }
  const rank = (/** @type {UiRec} */ rec) => { const at = WORKFLOW_TONE_RANK.indexOf(rec.tone || "amber"); return at < 0 ? 99 : at; };
  return recs.sort((a, b) => rank(a) - rank(b) || (b.money || 0) - (a.money || 0));
}

/** Draws a module's assistant into its `[data-wa-host]` slot. @param {string} module */
function renderModuleAssistant(module) {
  const host = document.querySelector(`[data-wa-host="${module}"]`);
  if (!host) return;
  host.innerHTML = uiWorkflowAssistant({ key: module, recs: workflowRecommendations(module), open: Boolean(workflowAssistantOpen[module]) });
}

/** @param {string} module */
function toggleModuleAssistant(module) {
  workflowAssistantOpen[module] = !workflowAssistantOpen[module];
  renderModuleAssistant(module);
  /** @type {HTMLElement | null} */ (document.querySelector(`[data-wa-toggle="${module}"]`))?.focus();
}

// ----- Stock cover -----
// Cover (months) = on hand ÷ average monthly units sold over the last 6 months. On hand counts
// unexpired lots only; on order is what open supplier POs still have to deliver. Units are the
// invoice line quantities by item code, the same basis Item Forecast uses.
/** @typedef {{ code: string, name: string, onHand: number, onOrder: number, avgMonthly: number, months: number | null }} StockCoverRow */
/** @param {Map<StockRow, string>} [statusOf] precomputed inventoryStatus per stock row @returns {StockCoverRow[]} */
function itemStockCover(statusOf) {
  const from = fmtDate(addMonthsToDate(today, -6));
  const to = fmtDate(today);
  /** @type {Record<string, number>} */
  const sold = {};
  for (const sale of data.sales) {
    if (sale.status === "Cancelled" || !dateInRange(sale.date, from, to)) continue;
    for (const line of /** @type {PoLine[]} */ (sale.lines?.length ? sale.lines : [{ code: sale.code, item: sale.item, qty: sale.qty }])) {
      const code = line.code || data.items.find((item) => item.name === line.item)?.code;
      if (code) sold[code] = (sold[code] || 0) + Number(line.qty || 0);
    }
  }
  /** @type {Record<string, number>} */
  const onHand = {};
  for (const row of data.inventory) {
    if (Number(row.qty) > 0 && (statusOf?.get(row) ?? inventoryStatus(row)) !== "Expired") onHand[row.code] = (onHand[row.code] || 0) + Number(row.qty || 0);
  }
  /** @type {Record<string, number>} */
  const onOrder = {};
  for (const po of data.inventoryPurchaseOrders || []) {
    if (inventoryPoTerminalStatuses.includes(po.status)) continue;
    for (const line of po.lines || []) {
      if (line.code) onOrder[line.code] = (onOrder[line.code] || 0) + Math.max(0, Number(line.qty || 0) - Number(line.receivedQty || 0));
    }
  }
  return data.items.filter((item) => !isArchived(item) && !isEquipmentItem(item)).map((item) => {
    const avgMonthly = (sold[item.code] || 0) / 6;
    const have = onHand[item.code] || 0;
    return { code: item.code, name: item.name, onHand: have, onOrder: onOrder[item.code] || 0, avgMonthly, months: avgMonthly > 0 ? have / avgMonthly : null };
  });
}

/** @param {any} value */
function monthLabel(value) {
  return new Date(`${value}-01T00:00:00`).toLocaleDateString("en-PH", { month: "short", year: "numeric" });
}

/** @param {any} entries @param {string} [label] */
function lineChart(entries, label = "Monthly sales line graph") {
  if (!entries.length) return `<p>No sales trend available for this view.</p>`;
  const width = 720;
  const height = 260;
  const pad = 42;
  const max = Math.max(...entries.map((/** @type {any[]} */ [, value]) => value), 1);
  const xStep = entries.length > 1 ? (width - pad * 2) / (entries.length - 1) : 0;
  const points = entries.map((/** @type {any[]} */ [, value], /** @type {any} */ index) => {
    const x = entries.length > 1 ? pad + index * xStep : width / 2;
    const y = height - pad - (value / max) * (height - pad * 2);
    return { x, y, value };
  });
  /** @type {Record<string, any>} */
  const line = points.map((/** @type {any} */ point) => `${point.x},${point.y}`).join(" ");
  const area = `${pad},${height - pad} ${line} ${points.at(-1).x},${height - pad}`;
  const gridlines = [0.25, 0.5, 0.75, 1].map((ratio) => {
    const y = height - pad - ratio * (height - pad * 2);
    return `<line class="chart-gridline" x1="${pad}" y1="${y}" x2="${width - pad}" y2="${y}"></line>${ratio === 0.5 || ratio === 1 ? `<text class="chart-text chart-y-label" x="${pad - 8}" y="${y + 4}" text-anchor="end">${escapeHtml(pesoCompact(max * ratio).replace(/\.00$/, ""))}</text>` : ""}`;
  }).join("");
  // Past about 8 month labels they collide, so show every nth, always keeping the latest month.
  const labelStep = Math.ceil(entries.length / 8);
  const showLabel = (/** @type {number} */ index) => (entries.length - 1 - index) % labelStep === 0;
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${escapeHtml(label)}">
    <defs><linearGradient id="salesTrendGradient" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#3db3cd" stop-opacity="0.28"/><stop offset="1" stop-color="#3db3cd" stop-opacity="0"/></linearGradient></defs>
    ${gridlines}<line class="chart-axis" x1="${pad}" y1="${height - pad}" x2="${width - pad}" y2="${height - pad}"></line>
    <polygon class="chart-area" points="${area}"></polygon><polyline class="chart-line" points="${line}"></polyline>
    ${points.map((/** @type {any} */ point, /** @type {any} */ index) => `<circle class="chart-point" cx="${point.x}" cy="${point.y}" r="7"><title>${monthLabel(entries[index][0])}: ${peso.format(point.value)}</title></circle>`).join("")}
    ${entries.map((/** @type {any[]} */ [month], /** @type {any} */ index) => showLabel(index) ? `<text class="chart-text" x="${points[index].x}" y="${height - 12}" text-anchor="middle">${escapeHtml(monthLabel(month))}</text>` : "").join("")}
  </svg>`;
}

/** @typedef {{ label: string, type?: string, color?: string, gradient?: any, dashed?: boolean, values: number[], format?: (v: number) => string }} ChartSeries */
/** @param {string[]} labels @param {ChartSeries[]} series @param {Record<string, any>} [options] */
function multiSeriesChart(labels, series, options = {}) {
  if (!labels.length) return `<p>No trend data available for this view.</p>`;
  // Drawn at the container's real pixel width (not a stretched fixed viewBox) so text stays
  // at its CSS size and labels never clip on narrow or very wide panels.
  const width = Math.max(280, Math.round(options.width || 760));
  const compact = width < 520;
  const height = compact ? 240 : 280;
  const barSeries = series.filter((s) => s.type === "bar");
  const lineSeries = series.filter((s) => s.type !== "bar");
  const max = Math.max(...series.flatMap((s) => s.values), 1);
  const kFmt = (/** @type {any} */ n) => (n >= 1e6 ? `${(n / 1e6).toFixed(n >= 1e7 ? 0 : 1)}M` : n >= 1000 ? `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k` : String(Math.round(n)));
  const ticks = [0, 0.25, 0.5, 0.75, 1];
  const longestTick = Math.max(...ticks.map((ratio) => kFmt(max * ratio).length));
  const padLeft = 16 + longestTick * 8;
  const padRight = 12;
  const padTop = 14;
  const padBottom = 34;
  const plotWidth = width - padLeft - padRight;
  const slot = plotWidth / labels.length;
  const groupCount = Math.max(barSeries.length, 1);
  const barGap = 4;
  const groupWidth = Math.min(28 * groupCount + barGap * (groupCount - 1), slot * 0.7);
  const barWidth = Math.max(3, (groupWidth - barGap * (groupCount - 1)) / groupCount);
  const xFor = (/** @type {any} */ index) => padLeft + slot * (index + 0.5);
  const yFor = (/** @type {any} */ value) => height - padBottom - (value / max) * (height - padTop - padBottom);
  const gridlines = ticks.map((ratio) => {
    const y = height - padBottom - ratio * (height - padTop - padBottom);
    return `<line class="chart-gridline" x1="${padLeft}" y1="${y}" x2="${width - padRight}" y2="${y}"></line>` +
      `<text class="chart-text" x="${padLeft - 8}" y="${y + 4}" text-anchor="end">${kFmt(max * ratio)}</text>`;
  }).join("");
  const gradSeries = barSeries.filter((s) => Array.isArray(s.gradient));
  const defs = gradSeries.length
    ? `<defs>${gradSeries.map((s) => {
        const id = `msc-bar-${barSeries.indexOf(s)}`;
        return `<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${s.gradient[0]}"/><stop offset="1" stop-color="${s.gradient[1]}"/></linearGradient>`;
      }).join("")}</defs>`
    : "";
  const tip = (/** @type {any} */ s, /** @type {any} */ index) => `${escapeHtml(s.label)} — ${escapeHtml(String(labels[index]))}: ${s.format ? s.format(s.values[index] || 0) : s.values[index] || 0}`;
  const bars = barSeries.map((s, si) => labels.map((_, index) => {
    const groupLeft = xFor(index) - groupWidth / 2;
    const x = groupLeft + si * (barWidth + barGap);
    const y = yFor(s.values[index] || 0);
    const barHeight = Math.max(2, height - padBottom - y);
    const fill = Array.isArray(s.gradient) ? `url(#msc-bar-${si})` : s.color;
    return `<rect class="chart-bar" x="${x}" y="${y}" width="${barWidth}" height="${barHeight}" rx="3" fill="${fill}"><title>${tip(s, index)}</title></rect>`;
  }).join("")).join("");
  const lines = lineSeries.map((s) => {
    const points = labels.map((_, index) => `${xFor(index)},${yFor(s.values[index] || 0)}`).join(" ");
    const dots = labels.map((_, index) => `<circle class="chart-multi-point" cx="${xFor(index)}" cy="${yFor(s.values[index] || 0)}" r="4.5" fill="${s.color}"><title>${tip(s, index)}</title></circle>`).join("");
    return `<polyline points="${points}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" ${s.dashed ? 'stroke-dasharray="6 5"' : ""}></polyline>${dots}`;
  }).join("");
  // Thin out month labels when slots are narrower than a label so they never overlap.
  const labelEvery = Math.max(1, Math.ceil((compact ? 64 : 76) / slot));
  const axisLabels = labels.map((label, index) => (labels.length - 1 - index) % labelEvery === 0
    ? `<text class="chart-text" x="${xFor(index)}" y="${height - 12}" text-anchor="middle">${escapeHtml(String(label))}</text>`
    : "").join("");
  const legend = series.map((s) => `<span class="chart-legend-item"><i style="background:${Array.isArray(s.gradient) ? s.gradient[0] : s.color}"></i>${escapeHtml(s.label)}</span>`).join("");
  return `<svg class="multi-series-chart" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="img" aria-label="Sales and collections trend">
    ${defs}${gridlines}<line class="chart-axis" x1="${padLeft}" y1="${height - padBottom}" x2="${width - padRight}" y2="${height - padBottom}"></line>
    ${bars}${lines}${axisLabels}
  </svg><div class="chart-legend-row">${legend}</div>`;
}

/** @param {any} entries @param {any} [subTextFn] */
function verticalBars(entries, subTextFn) {
  if (!entries.length) return `<p>No salesperson data available for this view.</p>`;
  const max = Math.max(...entries.map((/** @type {any[]} */ [, value]) => value), 1);
  return entries.map((/** @type {any[]} */ [label, value]) => `<div class="vertical-bar"><span class="vertical-value" title="${escapeHtml(peso.format(value))}">${escapeHtml(pesoCompact(value))}</span><div class="vertical-track"><span class="vertical-fill" style="height:${Math.max(6, Math.round((value / max) * 100))}%"></span></div><span class="vertical-label">${escapeHtml(label)}</span>${subTextFn ? `<span class="vertical-subvalue">${escapeHtml(subTextFn(label, value))}</span>` : ""}</div>`).join("");
}

/** @param {string} text @param {Record<string, any>} [options] */
function parseInvoiceLines(text, options = {}) {
  const requireLot = options.requireLot !== false;
  return text.split(/\r?\n/).map((row) => row.trim()).filter(Boolean).map((row) => {
    const [itemName, brandValue, qtyValue, uomValue, priceValue, sixthValue, seventhValue, eighthValue, discountValue] = row.split("|").map((cell) => cell.trim());
    const hasBranch = platformBranches().some((branch) => branch.toLowerCase() === String(sixthValue || "").toLowerCase());
    const sourceBranch = hasBranch ? sixthValue : "";
    const lotValue = hasBranch ? seventhValue : sixthValue;
    const expiryValue = hasBranch ? eighthValue : seventhValue;
    // Match the same way the live row preview does (findItemByCodeOrName: trimmed,
    // case-insensitive, with a partial fallback) instead of a strict exact string compare —
    // otherwise a row the UI already resolved (brand/stock hint filled in while typing) could
    // still fail here over nothing but a stray extra space or a case difference, and the only
    // clue was "Unknown item: <name>" even though that exact name was sitting in the masterlist.
    const item = findItemByCodeOrName(itemName);
    if (!item) throw new Error(`"${itemName}" was not found in the Items masterlist. Check the spelling, or add it under Masterlists → Items.`);
    if (isArchived(item) && !options.allowArchivedItems) throw new Error(`${item.name} is archived and can no longer be added to new transactions.`);
    const equipment = isEquipmentItem(item);
    const qty = Number(qtyValue);
    const price = Number(priceValue);
    // Fractional quantities are allowed (e.g. 0.5 of a reagent kit) — only zero, negative,
    // and non-numeric values are rejected here. Equipment is still whole-units only.
    if (!qty || qty <= 0 || Number.isNaN(price) || price < 0) throw new Error(`Invalid qty or price for ${item.name}`);
    if (equipment && !Number.isInteger(qty)) throw new Error(`${item.name} is equipment — quantity must be a whole number.`);
    if (requireLot && !lotValue && itemStockLotTracked(item, sourceBranch)) throw new Error(`Missing lot number for ${item.name}`);
    if (requireLot && !equipment && !uomSkipsExpiry(uomValue || item.uom) && !expiryValue) throw new Error(`Missing expiry date for ${item.name}`);
    return { item: item.name, code: item.code, brand: brandValue || item.brand, qty, uom: uomValue || item.uom || "unit", price, sourceBranch, branch: sourceBranch, lot: lotValue || "", expiry: equipment ? "N/A" : expiryValue || "", discount: Number(discountValue || 0), discountReason: "" };
  });
}

// Lot number and expiry are optional when receiving stock — an item that isn't
// tracked by expiry (or whose expiry was simply left blank on receipt) is stored
// with expiry "" or "N/A" interchangeably, not always the literal "N/A" string.
// Treating only "N/A" as "no expiry" made daysUntil("") — NaN — read as already
// expired, silently excluding real, in-stock units from availability checks.
/** @param {string} expiry */
function hasNoExpiry(expiry) {
  return !expiry || expiry === "N/A";
}

/** Lines sold per "unit" (machines, instruments) carry no expiry, so it's optional there. @param {unknown} uom */
function uomSkipsExpiry(uom) {
  return normalizeUom(uom) === "unit";
}

/** Expiry is required on an invoice row unless the item is equipment or the row's unit is "unit". @param {Element | null} row */
function syncInvoiceRowExpiryRequired(row) {
  if (!row) return;
  const expiryInput = qsIn(row, ".invoice-expiry-input");
  if (!expiryInput || expiryInput.type === "hidden") return;
  const item = findItemByCodeOrName(qsIn(row, ".invoice-item-input")?.value);
  expiryInput.required = !isEquipmentItem(item) && !uomSkipsExpiry(qsIn(row, ".invoice-uom-input")?.value);
}

/** @param {any} item */
function isEquipmentItem(item) {
  const category = String(item?.category || item?.classification || "").trim().toLowerCase();
  return category === "equipment";
}

/** @param {{ qty: number, price: number }} line */
function lineSubtotal(line) { return Math.max(0, line.qty * line.price); }
/** @param {Sale} sale */
function saleSummary(sale) { return (sale.lines || []).map((line) => `${line.item} (${line.qty} ${line.uom})`).join(", ") || `${sale.item} (${sale.qty || 0} ${sale.uom || "unit"})`; }
/** @param {Sale} sale */
function saleBrandSummary(sale) { return [...new Set((sale.lines || []).map((line) => line.brand).filter(Boolean))].join(", ") || sale.brand || "-"; }
/** @param {any[]} lines */
function saleAmount(lines) { return lines.reduce((sum, line) => sum + lineSubtotal(line), 0); }
/** @param {string} documentNo @param {any} [exceptId] */
function documentExists(documentNo, exceptId = null) {
  const normalized = String(documentNo || "").trim().toLowerCase();
  return data.sales.some((sale) => String(sale.documentNo || sale.id || "").trim().toLowerCase() === normalized && sale.id !== exceptId);
}
/** @param {string} receiptNo */
function receiptExists(receiptNo) {
  const normalized = String(receiptNo || "").trim().toLowerCase();
  return data.payments.some((payment) => String(payment.receiptNo || "").trim().toLowerCase() === normalized);
}
/** @param {string} branch */
function branchUsageReasons(branch) {
  return [
    data.inventory.some((item) => item.branch === branch) && "inventory stock",
    data.pendingTransfers.some((transfer) => transfer.from === branch || transfer.to === branch) && "stock transfers",
    data.sales.some((sale) => sale.sourceBranch === branch || (sale.lines || []).some((line) => line.sourceBranch === branch || line.branch === branch)) && "posted invoices",
    (data.inventoryPurchaseOrders || []).some((po) => po.branch === branch || po.receivingBranch === branch) && "inventory purchase orders",
  ].filter(Boolean);
}
/** @param {any} discount */
function discountNeedsApproval(discount) { return Number(discount || 0) > 0; }
/** @param {any} value */
function findItemByCodeOrName(value) {
  const query = String(value || "").trim().toLowerCase();
  if (!query) return null;
  return data.items.find((entry) => entry.code.toLowerCase() === query || entry.name.toLowerCase() === query)
    || data.items.find((entry) => entry.code.toLowerCase().startsWith(query) || entry.name.toLowerCase().startsWith(query))
    || data.items.find((entry) => entry.code.toLowerCase().includes(query) || entry.name.toLowerCase().includes(query));
}
/** @param {any} row @param {any} [changedInput] @param {boolean} [allowPartial] */
function findItemForSheetRow(row, changedInput = null, allowPartial = false) {
  const code = qsIn(row, ".stock-code, .transfer-code, .demo-line-code")?.value.trim().toLowerCase() || "";
  const name = qsIn(row, ".stock-item, .transfer-item, .demo-line-item")?.value.trim().toLowerCase() || "";
  const changedValue = String(changedInput?.value || "").trim().toLowerCase();
  const exact = data.items.find((entry) => entry.code.toLowerCase() === code)
    || data.items.find((entry) => entry.name.toLowerCase() === name)
    || data.items.find((entry) => entry.code.toLowerCase() === changedValue || entry.name.toLowerCase() === changedValue);
  if (exact || !allowPartial) return exact || null;
  return findItemByCodeOrName(changedInput?.value) || findItemByCodeOrName(code) || findItemByCodeOrName(name);
}
/** @param {any} type */
function collectionTagForType(type) { return type === "TS" ? "TS-PR" : ["DR", "DRS"].includes(type) ? "DR-CR" : "SI-CR"; }
// A Bounced payment has exactly one way forward — a Superadmin redeposits it (optionally with a
// corrected cheque number), which puts it back to For Deposit. Deposited/Posted Date are hidden
// until then so a bounced cheque can't be marked Deposited without being redeposited first.
/** @param {Payment} payment @param {string} buttonClass */
function collectionStatusButtonsHtml(payment, buttonClass) {
  const receiptNo = escapeHtml(payment.receiptNo);
  if (payment.collectionStatus === "Bounced") {
    return canRedepositCollections()
      ? `<button class="${buttonClass}" data-collection-redeposit="${receiptNo}">Redeposit</button>`
      : `<small>Bounced — awaiting Superadmin redeposit</small>`;
  }
  return `<button class="${buttonClass}" data-collection-status="${receiptNo}:Deposited">Deposited</button><button class="${buttonClass} danger-button" data-collection-status="${receiptNo}:Bounced">Bounced</button><button class="${buttonClass}" data-collection-status="${receiptNo}:Posted Date">Posted Date</button>`;
}

function canRedepositCollections() { return ["Superadmin", "CEO"].includes(currentUser?.role); }

/** @param {any} request */
function paymentRequestHistory(request) {
  return request.history?.length ? request.history : [{ date: request.date, status: request.requestStatus || request.status || "Prepared", note: "Payment request created.", by: request.preparedBy }];
}

/** @param {any} request */
function paymentRequestActionsCell(request) {
  const approveBtn = request.invoice && request.requestStatus === "Pending"
    ? (canApprovePaymentRequests() ? `<button class="mini-button" data-payment-request-approve="${escapeHtml(request.cvNo)}">Approve</button>` : `<small>Awaiting Superadmin/CEO</small>`)
    : "";
  const linkedPayment = data.payments.find((entry) => entry.paymentRequestCvNo === request.cvNo);
  const isDepositFinal = linkedPayment?.collectionStatus === "Deposited";
  const isCancellable = request.requestStatus === "Pending";
  const cancelBtn = isCancellable && canApprovePaymentRequests() ? `<button class="mini-button danger-button" data-payment-request-cancel="${escapeHtml(request.cvNo)}">Cancel</button>` : "";
  const statusActions = request.requestStatus === "Approved" && linkedPayment && !isDepositFinal
    ? collectionStatusButtonsHtml(linkedPayment, "mini-button")
    : "";
  const timelineBtn = `<button class="mini-button" data-payment-request-timeline="${escapeHtml(request.cvNo)}">View Timeline</button>`;
  const printBtn = `<button class="mini-button" data-payment-request-preview="${escapeHtml(request.cvNo)}">Preview / Print</button>`;
  const moreBtn = `<button class="mini-button" data-payment-request-more="${escapeHtml(request.cvNo)}">More...</button>`;
  const hasPrimaryActions = Boolean(approveBtn || cancelBtn || statusActions);
  const secondaryActions = hasPrimaryActions ? moreBtn : `${timelineBtn}${printBtn}`;
  return `<div class="inline-actions">${approveBtn}${cancelBtn}${statusActions}${secondaryActions}</div>`;
}

/** @param {string} cvNo */
function openPaymentRequestMoreMenu(cvNo) {
  qs("#payment-request-more-modal")?.remove();
  const dialog = document.createElement("dialog");
  dialog.className = "modal payment-request-more-modal";
  dialog.id = "payment-request-more-modal";
  dialog.innerHTML = `<form method="dialog"><div class="modal-header"><div><p class="eyebrow">${escapeHtml(cvNo)}</p><h2>More Actions</h2></div><button class="icon-button" value="cancel" formnovalidate aria-label="Close">x</button></div><div class="action-menu-list"><button class="ghost-button" type="button" data-payment-request-timeline="${escapeHtml(cvNo)}">View Timeline</button><button class="ghost-button" type="button" data-payment-request-preview="${escapeHtml(cvNo)}">Preview / Print</button></div></form>`;
  document.body.appendChild(dialog);
  dialog.addEventListener("close", () => dialog.remove());
  dialog.showModal();
}

/** @param {Payment} payment */
function saleForPayment(payment) {
  return data.sales.find((sale) => (sale.documentNo || sale.id) === payment.invoice || sale.id === payment.invoice || sale.documentNo === payment.invoice);
}

/** @param {Payment} payment */
function applyCollectionPayment(payment) {
  const sale = saleForPayment(payment);
  if (!sale) return;
  if (payment.appliedToInvoice === true) return;
  if (payment.appliedToInvoice === undefined) {
    // Legacy approved requests used to add paid amount immediately on approval.
    payment.appliedToInvoice = true;
    return;
  }
  sale.paid = Number(sale.paid || 0) + Number(payment.amount || 0);
  payment.appliedToInvoice = true;
}

/** @param {Payment} payment */
function reverseCollectionPayment(payment) {
  const sale = saleForPayment(payment);
  if (!sale) return;
  if (payment.appliedToInvoice === false) return;
  sale.paid = Math.max(Number(sale.paid || 0) - Number(payment.amount || 0), 0);
  payment.appliedToInvoice = false;
}

/** @param {any} requestOrCvNo */
function paymentRequestPayments(requestOrCvNo) {
  const cvNo = typeof requestOrCvNo === "string" ? requestOrCvNo : requestOrCvNo?.cvNo;
  return data.payments.filter((entry) => entry.paymentRequestCvNo === cvNo || entry.receiptNo === cvNo);
}

/** @param {string} cvNo */
async function approvePaymentRequest(cvNo) {
  if (!canApprovePaymentRequests()) return toast("Only Superadmin or CEO can approve payment requests.");
  const request = data.paymentRequests.find((entry) => entry.cvNo === cvNo);
  if (!request) return toast("Payment request not found.");
  const invoiceIds = request.invoices?.length ? request.invoices : (request.invoice ? request.invoice.split(",").map((id) => id.trim()).filter(Boolean) : []);
  if (!invoiceIds.length) return toast("This payment request is not linked to an invoice.");
  if (request.requestStatus !== "Pending") return toast("This payment request has already been processed.");
  const sales = /** @type {any[]} */ (invoiceIds.map((/** @type {any} */ id) => findSaleByDocumentInput(id)).filter(Boolean));
  if (!sales.length) return toast("Linked invoice(s) not found.");
  // Requests created with the per-invoice itemized editor carry an explicit net amount for
  // each invoice (item.netAmount). Older requests only have one lump total, so fall back to
  // applying that sequentially, oldest invoice first — matches the payment behavior those
  // requests were originally created and approved under.
  const perInvoiceItems = (request.items || []).filter((/** @type {any} */ item) => item.invoice && item.netAmount != null);
  const hasPerInvoiceAmounts = perInvoiceItems.length > 0;
  const combinedBalance = sales.reduce((sum, sale) => sum + Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0), 0);
  const requestedAmount = Number(request.total || request.amount || 0);
  // Compare rounded to the centavo: combinedBalance is built from chained float subtraction/addition
  // across invoices, so a request for the "exact" balance can land a fraction of a centavo over it
  // (e.g. 3642.8600000000001) and wrongly trip a strict > comparison.
  if (roundMoney(requestedAmount) - roundMoney(combinedBalance) > 0.01) return toast(`Cannot approve: requested ${peso.format(requestedAmount)} exceeds the combined remaining balance of ${peso.format(combinedBalance)}.`);
  const isFull = roundMoney(combinedBalance) - roundMoney(requestedAmount) <= 0.01;
  const ok = await confirmDetailsModal({
    eyebrow: "Confirm Approval",
    title: `Approve ${request.cvNo}`,
    fields: [["Invoice(s)", sales.map((sale) => sale.documentNo || sale.id).join(", ")], ["Client", sales[0].client], ["Requested Amount", peso.format(requestedAmount)], ["Combined Balance", peso.format(combinedBalance)]],
    confirmLabel: "Approve & Record Payment",
    note: hasPerInvoiceAmounts ? "This will apply the specified amount to each selected invoice." : isFull ? "This will fully settle the selected invoice(s)." : "This will be recorded as a partial payment, applied to the oldest invoice first.",
  });
  if (!ok) return;
  const by = currentUser?.name || "System User";
  /** @type {any[]} */
  const newPayments = [];
  /** @type {any[]} */
  const touchedSales = [];
  const applyPayment = (/** @type {Sale} */ sale, /** @type {any} */ applied) => {
    if (applied <= 0) return;
    const payment = { invoice: sale.documentNo || sale.id, tag: collectionTagForType(sale.type), receiptNo: request.cvNo, method: request.paymentType || "Cash", bank: request.bank || "", bankAccount: request.bankAccount || "", reference: request.paymentType === "Multiple Cheques" ? request.cheque || "" : "", chequeDate: request.chequeDate || "", cheques: Array.isArray(request.cheques) ? request.cheques.map((cheque) => ({ ...cheque })) : [], transferDate: request.transferDate || "", dateCollected: request.transferDate || fmtDate(today), dateRecorded: fmtDate(today), client: sale.client, amount: applied, collectionStatus: "For Deposit", appliedToInvoice: false, statusHistory: collectionStatusHistory("For Deposit"), paymentRequestCvNo: request.cvNo };
    data.payments.push(payment);
    // Applied as soon as it's posted (queued for deposit), not gated on deposit confirmation,
    // so the receivable balance reflects partial payments right away. Bounced reverses it back.
    applyCollectionPayment(payment);
    newPayments.push(payment);
    if (!touchedSales.includes(sale)) touchedSales.push(sale);
  };
  if (hasPerInvoiceAmounts) {
    perInvoiceItems.forEach((/** @type {any} */ item) => {
      const sale = sales.find((entry) => (entry.documentNo || entry.id) === item.invoice);
      if (!sale) return;
      const balance = Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0);
      applyPayment(sale, Math.min(balance, Number(item.netAmount || 0)));
    });
  } else {
    let remaining = requestedAmount;
    [...sales].sort((a, b) => new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime()).forEach((sale) => {
      if (remaining <= 0) return;
      const balance = Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0);
      if (balance <= 0) return;
      const applied = Math.min(balance, remaining);
      remaining -= applied;
      applyPayment(sale, applied);
    });
  }
  request.requestStatus = "Approved";
  request.status = "Approved";
  request.approvedBy = by;
  request.approvedAt = fmtDate(today);
  request.history = paymentRequestHistory(request);
  request.history.push({ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status: "Approved", note: `Approved by ${by}. ${isFull ? "Full" : "Partial"} payment of ${peso.format(requestedAmount)} queued for deposit across ${sales.length} invoice(s)${hasPerInvoiceAmounts ? ", per specified invoice amount" : ", oldest first"}. Invoice paid amount updated now; it reverses only if the deposit later bounces.`, by });
  const saveResult = await persistRecords({ paymentRequests: [request], payments: newPayments, sales: touchedSales });
  if (!saveResult?.ok) return;
  log("Approved payment request", "Collections", `${request.cvNo}: ${peso.format(requestedAmount)} queued for deposit (${isFull ? "Full" : "Partial"})`, { save: false });
  notify("Payment Received", `${request.cvNo} approved — pending bank deposit.`, "collections", request.cvNo);
  if (request.createdByUser) notify("Payment Received", `Your payment request ${request.cvNo} was approved.`, "notifications", request.cvNo, null, request.createdByUser);
  saveData(["notifications"]);
  renderAll();
  toast(`${request.cvNo} approved and queued for deposit.`);
}

/** @param {string} cvNo */
async function cancelPaymentRequest(cvNo) {
  if (!canApprovePaymentRequests()) return toast("Only Superadmin or CEO can cancel payment requests.");
  const request = data.paymentRequests.find((entry) => entry.cvNo === cvNo);
  if (!request) return toast("Payment request not found.");
  if (request.requestStatus === "Cancelled") return toast("This payment request is already cancelled.");
  if (request.requestStatus === "Approved") return toast("Approved payment requests cannot be cancelled. Update the collection status instead.");
  const payment = data.payments.find((entry) => entry.paymentRequestCvNo === request.cvNo);
  if (payment?.collectionStatus === "Deposited") return toast("This payment has already been deposited and can no longer be cancelled.");
  const sale = request.invoice ? findSaleByDocumentInput(request.invoice) : null;
  const { ok, reason } = await confirmDetailsModal({
    eyebrow: "Confirm Cancellation",
    title: `Cancel ${request.cvNo}`,
    fields: [["Invoice", request.invoice || "-"], ["Client", request.employee], ["Total", peso.format(request.total || 0)], ["Status", request.requestStatus || request.status || "-"]],
    confirmLabel: "Cancel Request",
    danger: true,
    collectReason: true,
    reasonLabel: "Reason for cancellation",
    note: payment ? "This will also reverse the recorded payment and the invoice's paid amount, since the payment has not been deposited yet." : "",
  });
  if (!ok) return;
  if (!reason) return toast("A cancellation reason is required.");
  const by = currentUser?.name || "System User";
  if (payment && sale) {
    sale.paid = Math.max(Number(sale.paid || 0) - Number(payment.amount || 0), 0);
    payment.collectionStatus = "Cancelled";
    payment.voided = true;
    payment.statusHistory ||= [];
    payment.statusHistory.push(...collectionStatusHistory("Cancelled"));
  }
  request.requestStatus = "Cancelled";
  request.status = "Cancelled";
  request.cancelledBy = by;
  request.cancelledAt = fmtDate(today);
  request.cancelReason = reason;
  request.history = paymentRequestHistory(request);
  request.history.push({ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status: "Cancelled", note: `Cancelled by ${by}. Reason: ${reason}`, by });
  const saveResult = await persistRecords({ paymentRequests: [request], payments: payment ? [payment] : [], sales: sale ? [sale] : [] });
  if (!saveResult?.ok) return;
  log("Cancelled payment request", "Collections", `${request.cvNo}: ${reason}`, { save: false });
  notify("Payment Received", `${request.cvNo} cancelled.`, "collections", request.cvNo);
  if (request.createdByUser) notify("Payment Received", `Your payment request ${request.cvNo} was cancelled.`, "notifications", request.cvNo, null, request.createdByUser);
  saveData(["notifications"]);
  renderAll();
  toast(`${request.cvNo} cancelled.`);
}

/** @param {any} cvNo */
function renderPaymentRequestDetail(cvNo) {
  ensureUploadedFilesLoaded(() => renderPaymentRequestDetail(cvNo));
  const request = data.paymentRequests.find((entry) => entry.cvNo === cvNo);
  if (!request) return toast("Payment request not found.");
  const events = paymentRequestHistory(request);
  const payment = data.payments.find((entry) => entry.paymentRequestCvNo === request.cvNo);
  const depositHistory = payment?.statusHistory?.length ? payment.statusHistory.map((/** @type {any} */ entry) => `<li>${escapeHtml(entry.date)} · ${escapeHtml(entry.status)} · ${escapeHtml(entry.user || "System User")}</li>`).join("") : `<li>No status history yet.</li>`;
  const isDepositFinal = payment?.collectionStatus === "Deposited" || request.requestStatus === "Cancelled";
  const depositActions = isDepositFinal
    ? `<p class="page-description">${request.requestStatus === "Cancelled" ? "This payment request was cancelled." : "Deposited — this payment is final and its status can no longer be changed."}</p>`
    : payment ? `<div class="modal-actions collection-status-actions">${collectionStatusButtonsHtml(payment, "ghost-button")}</div>` : "";
  const depositSection = payment ? `<div class="collection-detail-card"><header><div><span class="eyebrow">Deposit</span><strong>${escapeHtml(payment.receiptNo)}</strong><small>${peso.format(Number(payment.amount || 0))}${payment.postedDate ? ` · Posted ${escapeHtml(payment.postedDate)}` : ""}</small></div><span class="pill ${statusClass(payment.collectionStatus || "For Deposit")}">${escapeHtml(payment.collectionStatus || "For Deposit")}</span></header><div class="collection-history-panel"><h3>Deposit Status History</h3><ul>${depositHistory}</ul></div>${depositActions}</div>` : "";
  const physicalCopySection = request.requestStatus === "Approved" ? `<div class="collection-detail-card"><header><div><span class="eyebrow">Physical Copy</span><strong>Signed CV Voucher</strong><small>Upload a photo/scan of the physically signed and released voucher.</small></div></header>${attachedFilesHtml("paymentRequest", request.cvNo)}<div class="modal-actions"><button class="ghost-button" data-upload-copy="${escapeHtml(request.cvNo)}" type="button">Upload Physical Copy</button><input type="file" accept="image/*" class="physical-copy-input" data-record-type="paymentRequest" data-record-id="${escapeHtml(request.cvNo)}" data-rerender="payment-request-detail" hidden /></div></div>` : "";
  qs("#payment-request-detail-title").textContent = `${request.cvNo} · ${request.employee}`;
  qs("#payment-request-detail-panel").innerHTML = `<div class="panel-header"><div><p class="eyebrow">${escapeHtml(request.employee || "-")}</p><h2>${escapeHtml(request.invoice ? `Linked to ${request.invoice}` : "CV Voucher")}</h2></div><span class="pill ${statusClass(request.requestStatus || request.status)}">${escapeHtml(request.requestStatus || request.status || "-")}</span></div><div class="report-preview-grid invoice-mini-grid"><div class="report-preview-card"><small>Date</small><strong>${escapeHtml(request.date || "-")}</strong></div><div class="report-preview-card"><small>Total</small><strong>${peso.format(request.total || 0)}</strong></div><div class="report-preview-card"><small>Prepared By</small><strong>${escapeHtml(request.preparedBy || "-")}</strong></div><div class="report-preview-card"><small>Approved By</small><strong>${escapeHtml(request.approvedBy || "-")}</strong></div></div>${depositSection}${physicalCopySection}<details class="full-event-details" open><summary>Status timeline</summary><div class="event-timeline">${events.map((/** @type {any} */ event) => `<div class="event-item ${event.status === "Approved" ? "done" : "pending"}"><span>${escapeHtml((event.status || "P")[0])}</span><time>${escapeHtml(event.date || "")}</time><div><strong>${escapeHtml(event.status || "")}</strong><p>${escapeHtml(event.note || "-")}</p><small>${escapeHtml(event.by || "-")}</small></div></div>`).join("")}</div></details>`;
  showSection("payment-request-detail");
}

/** @param {string} [clientName] */
function openInvoicesForPaymentRequest(clientName = "") {
  return data.sales.filter((sale) => sale.status !== "Cancelled" && Number(sale.net || 0) - Number(sale.paid || 0) > 0 && (!clientName || sale.client === clientName))
    .sort((a, b) => new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime());
}

function refreshPaymentRequestInvoiceRowOptions() {
  const clientName = qs("#employee")?.value.trim() || "";
  qsa(".payment-request-invoice-row").forEach((row) => {
    const datalist = qsIn(row, "datalist");
    if (datalist) datalist.innerHTML = paymentRequestInvoiceDatalistOptions(clientName);
    syncPaymentRequestRowDerived(row);
  });
  syncPaymentRequestTotal();
}

function collectPaymentRequestInvoices() {
  if (paymentRequestPreselectedInvoice) return [paymentRequestPreselectedInvoice];
  return collectPaymentRequestLines().map((line) => line.invoice).filter(Boolean);
}

/** @param {any} value */
function findSaleByDocumentInput(value) {
  const query = String(value || "").trim().toLowerCase();
  if (!query) return null;
  return data.sales.find((item) => (item.id || "").toLowerCase() === query || (item.documentNo || "").toLowerCase() === query)
    || data.sales.find((item) => (item.id || "").toLowerCase().startsWith(query) || (item.documentNo || "").toLowerCase().startsWith(query));
}

// Lots an invoice line can draw from: on hand at the branch, not expired, earliest expiry first.
// While a Cancel & Replace is open, the invoice being cancelled gives its stock back on save, so its
// lots count with that quantity added — otherwise reusing the same lot would show nothing to pick.
/** @param {any} item @param {string} branch */
function invoiceSelectableLots(item, branch) {
  if (!item) return [];
  const cancelling = cancelReplaceSaleId ? data.sales.find((sale) => sale.id === cancelReplaceSaleId && !sale.noPo) : null;
  const returnedQty = (/** @type {StockRow} */ entry) => (cancelling?.lines || []).filter((line) => line.code === entry.code && (line.sourceBranch || line.branch) === entry.branch && line.lot === entry.lot).reduce((sum, line) => sum + Number(line.qty || 0), 0);
  return data.inventory
    .filter((entry) => (entry.code === item.code || entry.item === item.name) && (!branch || entry.branch === branch) && entry.lot && (hasNoExpiry(entry.expiry) || !isExpiredDate(entry.expiry)))
    .map((entry) => ({ lot: entry.lot, expiry: entry.expiry || "N/A", qty: Number(entry.qty || 0) + returnedQty(entry) }))
    .filter((entry) => entry.qty > 0)
    .sort((a, b) => daysUntil(hasNoExpiry(a.expiry) ? "2099-12-31" : a.expiry) - daysUntil(hasNoExpiry(b.expiry) ? "2099-12-31" : b.expiry));
}

// The lot is picked from a dropdown of what is actually in stock (expiry fills itself in). Only an
// item with no lot on file at the branch keeps a free-text box, so a lot can be recorded for it.
/** @param {any} item @param {string} branch @param {string} lot */
function invoiceLotControlHtml(item, branch, lot) {
  const uid = ++invoiceRowUid;
  const equipment = isEquipmentItem(item);
  const label = `<label>${equipment ? "Serial/Lot No." : "Lot No."}</label>`;
  const current = String(lot || "").trim();
  if (!itemStockLotTracked(item, branch)) return `${label}<input class="invoice-lot-input" name="invoice-lot-${uid}" autocomplete="off" value="${escapeHtml(current)}" placeholder="No lot on file — enter it here to record it" />`;
  const lots = invoiceSelectableLots(item, branch);
  const missing = current && !lots.some((entry) => entry.lot === current) ? `<option value="${escapeHtml(current)}" selected>${escapeHtml(current)} · not in stock here</option>` : "";
  const options = lots.map((entry) => `<option value="${escapeHtml(entry.lot)}"${entry.lot === current ? " selected" : ""}>${escapeHtml(entry.lot)} · Exp ${escapeHtml(entry.expiry)} · Qty ${entry.qty}</option>`).join("");
  return `${label}<select class="invoice-lot-input" name="invoice-lot-${uid}" required><option value="">${lots.length ? "Select lot" : "No lot in stock"}</option>${missing}${options}</select>`;
}

// Exact code+branch+lot+qty match first. If that misses and there's an untracked (no lot
// on file) row with enough qty, fall back to it — this is what lets a lot typed during
// invoicing "claim" stock that was received without one (see itemStockLotTracked).
/** @param {PoLine} line */
function matchInvoiceLineStock(line) {
  return data.inventory.find((i) => i.code === line.code && i.branch === line.sourceBranch && i.lot === line.lot && i.qty >= line.qty)
    || data.inventory.find((i) => i.code === line.code && i.branch === line.sourceBranch && !i.lot && i.qty >= line.qty);
}

/** @param {any} item @param {string} branch */
function itemStockLotTracked(item, branch) {
  if (!item) return true;
  const entries = data.inventory.filter((entry) => (entry.code === item.code || entry.item === item.name) && (!branch || entry.branch === branch) && entry.qty > 0);
  return entries.length ? entries.some((entry) => entry.lot) : true;
}

/** @param {any} item @param {string} branch */
function invoiceItemStockQty(item, branch) {
  if (!item) return 0;
  return data.inventory
    .filter((entry) => (entry.code === item.code || entry.item === item.name) && (!branch || entry.branch === branch) && entry.qty > 0 && (hasNoExpiry(entry.expiry) || !isExpiredDate(entry.expiry)))
    .reduce((sum, entry) => sum + Number(entry.qty || 0), 0);
}

// What a given lot would actually resolve to under matchInvoiceLineStock()'s rules: an exact
// lot match, or (if no row on file for this item/branch has a lot at all) any untracked row.
// invoiceItemStockQty() above is a lot-blind total — it can say "1 available" while the one
// unit on hand sits under a different lot than the one typed, which only surfaces as a save-time
// "No sufficient stock" error. This keeps the hint honest once a lot is entered.
/** @param {any} item @param {string} branch @param {string} lot */
function invoiceItemStockQtyForLot(item, branch, lot) {
  if (!item) return 0;
  const trimmedLot = String(lot || "").trim();
  if (!trimmedLot) return invoiceItemStockQty(item, branch);
  const candidates = data.inventory.filter((entry) => (entry.code === item.code || entry.item === item.name) && (!branch || entry.branch === branch) && entry.qty > 0 && (hasNoExpiry(entry.expiry) || !isExpiredDate(entry.expiry)) && (entry.lot === trimmedLot || !entry.lot));
  return candidates.reduce((max, entry) => Math.max(max, Number(entry.qty || 0)), 0);
}

/** @param {any} item @param {string} branch @param {string} lot */
function invoiceRowStockHintHtml(item, branch, lot) {
  if (!item) return "";
  const trimmedLot = String(lot || "").trim();
  const qty = invoiceItemStockQtyForLot(item, branch, trimmedLot);
  const uom = item.uom || "unit";
  const reserved = pendingPoDemandForItem(item.code, branch, qs("#po")?.value || null);
  const lotNote = trimmedLot ? ` for lot ${escapeHtml(trimmedLot)}` : "";
  // A zero-stock hint reads the same whether the branch just happens to be low right now or the
  // item is never stocked there at all — naming the branch that actually has it catches the
  // common "picked the wrong Stock From branch" case before the user even tries to save.
  const elsewhereBranches = qty <= 0 && branch ? [...new Set(data.inventory.filter((entry) => (entry.code === item.code || entry.item === item.name) && entry.branch !== branch && entry.qty > 0).map((entry) => entry.branch))] : [];
  const availability = qty > 0
    ? `${qty} ${escapeHtml(uom)}${qty === 1 ? "" : "s"} available${branch ? ` at ${escapeHtml(branch)}` : ""}${lotNote}`
    : `No stock available${branch ? ` at ${escapeHtml(branch)}` : ""}${lotNote}${elsewhereBranches.length ? ` — available at ${elsewhereBranches.map(escapeHtml).join(" and ")}` : ""}`;
  // Always shown, not just when > 0 — a row with 1 available and 2 already pending on other
  // POs needs to read the same at a glance as one with 1 available and 0 pending, instead of
  // only growing a note once there's a problem (see the VEDA8900 "1 available" confusion).
  const pendingNote = ` (${reserved} ${escapeHtml(uom)}${reserved === 1 ? "" : "s"} pending)`;
  return `<small class="invoice-stock-hint${qty <= 0 ? " invoice-stock-hint-empty" : ""}${reserved > 0 ? " invoice-stock-hint-reserved" : ""}" data-role="stock-hint">${availability}${pendingNote}</small>`;
}

/** @param {Record<string, any>} [line] @param {Record<string, any>} [options] */
function invoiceLineTemplate(line = {}, options = {}) {
  const requireLot = options.requireLot !== false;
  const allowDiscount = Boolean(options.allowDiscount);
  const showCode = Boolean(options.showCode);
  const item = findItemByCodeOrName(line.code || line.item || line.name);
  const equipment = isEquipmentItem(item);
  const selectedInvoiceBranch = qs("#sourceBranch")?.value || line.sourceBranch || line.branch || inventoryBranchTab || platformBranches()[0] || "";
  const preferredBranch = selectedInvoiceBranch;
  const stock = item ? data.inventory.find((entry) => (entry.code === item.code || entry.item === item.name) && entry.branch === preferredBranch) || /** @type {Partial<StockRow>} */ ({}) : /** @type {Partial<StockRow>} */ ({});
  const lotTracked = itemStockLotTracked(item, preferredBranch);
  const selectedUom = normalizeUom(line.uom || item?.uom) || "unit";
  const uid = ++invoiceRowUid;
  return `<div class="invoice-line-row">
    <div class="invoice-line-fields">
      ${showCode ? `<div class="field code-field"><label>Item Code</label><input class="invoice-code-input" name="invoice-code-${uid}" list="item-code-options" autocomplete="off" value="${escapeHtml(line.code || item?.code || "")}" placeholder="Type or pick a code" /></div>` : ""}
      <div class="field item-field"><label>Item</label><input class="invoice-item-input" name="invoice-item-${uid}" list="item-master-options" autocomplete="off" value="${escapeHtml(line.item || item?.name || "")}" placeholder="Type item or code" required />${invoiceRowStockHintHtml(item, preferredBranch, line.lot || stock.lot || "")}</div>
      <input class="invoice-source-branch-input" type="hidden" value="${escapeHtml(selectedInvoiceBranch)}" />
      <div class="field brand-field"><label>Brand</label><input class="invoice-brand-input" value="${escapeHtml(line.brand || item?.brand || "")}" readonly /></div>
      <div class="field qty-field"><label>Qty</label><input class="invoice-qty-input" type="number" min="0" step="any" value="${line.qty ? Number(line.qty) : ""}" required /></div>
      <div class="field unit-field"><label>Unit</label><select class="invoice-uom-input" required>${(uomOptions.includes(selectedUom) ? uomOptions : [...uomOptions, selectedUom]).map((uom) => `<option ${uom === selectedUom ? "selected" : ""}>${uom}</option>`).join("")}</select></div>
      <div class="field price-field"><label>Price</label><input class="invoice-price-input" type="number" min="0" step="any" value="${line.price || ""}" required /></div>
      ${requireLot ? `<div class="field lot-field">${invoiceLotControlHtml(item, preferredBranch, lotTracked ? line.lot || stock.lot || "" : line.lot || "")}</div><div class="field expiry-field${equipment ? " equipment-expiry-field" : ""}"><label>Expiry</label><input class="invoice-expiry-input" type="date" data-expiry-lot="${escapeHtml(line.lot || stock.lot || "")}" min="${fmtDate(today)}" value="${escapeHtml(equipment ? "" : line.expiry && line.expiry !== "N/A" ? line.expiry : stock.expiry && stock.expiry !== "N/A" ? stock.expiry : "")}" ${equipment || uomSkipsExpiry(selectedUom) ? "" : "required"}${lotTracked ? " readonly" : ""} /></div>` : `<input class="invoice-lot-input" type="hidden" value="" /><input class="invoice-expiry-input" type="hidden" value="" />`}
      ${allowDiscount ? `<div class="field"><label>Discount</label><input class="invoice-discount-input" type="number" min="0" step="any" value="${line.discount || ""}" /></div>` : `<input class="invoice-discount-input" type="hidden" value="${line.discount || 0}" />`}
    </div>
    <button class="icon-button remove-invoice-line" type="button" aria-label="Remove item" title="Remove item">×</button>
  </div>`;
}

/** @param {any} value */
function findClientByName(value) {
  const query = String(value || "").trim().toLowerCase();
  if (!query) return null;
  return data.clients.find((client) => client.name.toLowerCase() === query)
    || data.clients.find((client) => client.name.toLowerCase().includes(query));
}

/** @param {any} po @param {string} code */
function poServedQty(po, code) {
  return data.sales
    .filter((sale) => sale.po === po.id && sale.status !== "Cancelled" && sale.id !== cancelReplaceSaleId)
    .flatMap((sale) => sale.lines || [])
    .filter((line) => line.code === code)
    .reduce((sum, line) => sum + Number(line.qty || 0), 0);
}

/** @param {any} po @param {PoLine} line */
function poLineStatus(po, line) {
  const served = poServedQty(po, line.code);
  return { served, pending: Math.max(Number(line.qty || 0) - served, 0) };
}

// A submitted client PO can still be edited only while nothing has been invoiced/served
// against it and it is not in a terminal (fully served) status. Once any quantity is served,
// the PO is locked — corrections then go through the invoice cancel/replace flow instead.
/** @param {any} po */
function poHasAnyServed(po) {
  return (po?.lines || []).some((/** @type {any} */ line) => poServedQty(/** @type {ClientPO} */ (po), line.code) > 0);
}
/** @param {any} po */
function poCanEdit(po) {
  return Boolean(po) && !PO_TERMINAL_STATUSES.includes(poStatus(/** @type {ClientPO} */ (po))) && !poHasAnyServed(po) && canEditModule("purchase-orders");
}

/** @type {Record<string, any>} */
const PO_COMPLETED_DOC_LABELS = { SI: "Sales Invoice", TS: "Transmittal Slip", DR: "Delivery Receipt" };
const PO_TERMINAL_STATUSES = Object.values(PO_COMPLETED_DOC_LABELS);

/** @param {any} po */
function poStatus(po) {
  const pending = (po.lines || []).reduce((/** @type {number} */ sum, /** @type {any} */ line) => sum + poLineStatus(po, line).pending, 0);
  const served = (po.lines || []).reduce((/** @type {number} */ sum, /** @type {any} */ line) => sum + poLineStatus(po, line).served, 0);
  // Epsilon tolerance so fractional line quantities (e.g. 0.1 + 0.2) that sum to a hair
  // above zero from floating-point drift don't leave a fully-served PO stuck as pending.
  if (pending <= 1e-9) return PO_COMPLETED_DOC_LABELS[po.completedType] || "Sales Invoice";
  if (served > 0) return "Pending Orders";
  return "For Invoicing";
}

// How much of an item's stock at a branch is already claimed by pending/partially-invoiced
// POs (not yet fully served). Surfaced on the Stocks table so a "1 in stock" row that reads
// as available isn't a surprise "No stock available" once someone tries to invoice it, and
// enforced in buildSale() so one PO can't silently eat stock another open PO is waiting on.
/** @param {string} code @param {string} branch @param {string | null} [excludePoId] */
function competingPurchaseOrdersForItem(code, branch, excludePoId = null) {
  return data.purchaseOrders
    .filter((po) => po.id !== excludePoId && warehouseForArea(po.area) === branch)
    .map((po) => ({ po, pending: (po.lines || []).filter((line) => line.code === code).reduce((sum, line) => sum + poLineStatus(po, line).pending, 0) }))
    .filter((entry) => entry.pending > 0);
}

/** @param {string} code @param {string} branch @param {string | null} [excludePoId] */
function pendingPoDemandForItem(code, branch, excludePoId = null) {
  return competingPurchaseOrdersForItem(code, branch, excludePoId).reduce((sum, entry) => sum + entry.pending, 0);
}

/** @param {StockRow} item */
function inventoryReservedCellHtml(item) {
  const competitors = competingPurchaseOrdersForItem(item.code, item.branch);
  const reserved = competitors.reduce((sum, entry) => sum + entry.pending, 0);
  if (!reserved) return `<span class="muted-cell">—</span>`;
  const firstPoId = escapeHtml(competitors[0].po.id);
  // Open PO lines only record item code + branch, never a specific lot — which lot a sale draws
  // from is picked at invoicing time, not reserved in advance. So this total is the SAME demand
  // figure repeated on every lot row of this item at this branch (it's shared against their
  // combined stock, not per-lot), and the label/tooltip spell that out so two "24 pending" lot
  // rows don't read as 48 units reserved. The red/orange threshold below has to compare against
  // that same combined total too — comparing it to just this one lot's qty could flag the exact
  // same reserved figure red on one lot's row and orange on another lot's row of the same item.
  const totalStock = data.inventory.filter((stock) => stock.code === item.code && stock.branch === item.branch).reduce((sum, stock) => sum + Number(stock.qty || 0), 0);
  const title = `${reserved} unit${reserved === 1 ? "" : "s"} pending across open purchase orders for ${escapeHtml(item.item)} at ${escapeHtml(item.branch)} — shared across all lots of this item/branch (POs don't reserve a specific lot), not per-lot: ${competitors.map((entry) => `${entry.po.id} (${entry.po.client}) x${entry.pending}`).join(", ")}`;
  return `<button type="button" class="pill ${reserved > totalStock ? "red" : "orange"} pill-button" title="${title}" data-go-section="purchase-orders" data-focus-record="${firstPoId}">${reserved} pending (all lots)</button>`;
}

/** @param {any} po */
function poFullyPaid(po) {
  const linkedSales = data.sales.filter((sale) => sale.po === po.id && sale.status !== "Cancelled");
  return linkedSales.length > 0 && linkedSales.every((sale) => Number(sale.paid || 0) >= Number(sale.net || 0));
}

/** @param {any} po */
function poInvoiceable(po) {
  return !PO_TERMINAL_STATUSES.includes(poStatus(po)) && !poFullyPaid(po);
}

/** @param {string} clientName */
function openPurchaseOrdersForClient(clientName) {
  return data.purchaseOrders.filter((po) => po.client === clientName && poInvoiceable(po));
}

/** @param {any[]} [lines] @param {Record<string, any>} [options] */
function renderInvoiceEditor(lines = [{}], options = {}) {
  const requireLot = options.requireLot !== false;
  const allowDiscount = Boolean(options.allowDiscount);
  const showCode = Boolean(options.showCode);
  const help = requireLot ? "Search item name. Enter lot and expiry before creating SI, TS, or DR." : "Search item name. Lot and expiry will be entered during invoicing.";
  return `<div class="field full invoice-editor"><label>Itemized Lines</label><datalist id="item-master-options">${activeItems().map((item) => `<option value="${escapeHtml(item.name)}">${escapeHtml(item.code)} · ${escapeHtml(item.brand)}</option>`).join("")}</datalist>${showCode ? `<datalist id="item-code-options">${activeItems().map((item) => `<option value="${escapeHtml(item.code)}">${escapeHtml(item.name)}</option>`).join("")}</datalist>` : ""}<div class="invoice-line-list" id="invoice-line-list">${lines.map((line) => invoiceLineTemplate(line, { requireLot, allowDiscount, showCode })).join("")}</div><div class="invoice-editor-actions"><button class="ghost-button" id="add-invoice-line" type="button">Add Item</button><small>${help}${allowDiscount ? " Each line can include discount." : ""}</small></div><input id="itemsText" name="itemsText" type="hidden" /><div class="invoice-compute-preview" id="invoice-compute-preview"></div></div>`;
}

function collectInvoiceEditorLines() {
  return qsa(".invoice-line-row").map((row) => {
    const itemValue = qsIn(row, ".invoice-item-input").value.trim();
    const sourceBranch = qs("#sourceBranch")?.value || qsIn(row, ".invoice-source-branch-input")?.value.trim() || "";
    const brand = qsIn(row, ".invoice-brand-input").value.trim();
    const qty = qsIn(row, ".invoice-qty-input").value;
    const uom = qsIn(row, ".invoice-uom-input").value;
    const price = qsIn(row, ".invoice-price-input").value;
    const lot = qsIn(row, ".invoice-lot-input").value.trim();
    const item = findItemByCodeOrName(itemValue);
    const expiry = isEquipmentItem(item) ? "N/A" : qsIn(row, ".invoice-expiry-input").value;
    if (isExpiredDate(expiry)) throw new Error("Expiry date cannot be in the past.");
    const discount = qsIn(row, ".invoice-discount-input")?.value || 0;
    return `${itemValue}|${brand}|${qty}|${uom}|${price}|${sourceBranch}|${lot}|${expiry}|${discount}`;
  }).filter((line) => line.split("|")[0]).join("\n");
}

// Inventory PO lines carry an Item Code field: picking a code fills the item (and, through
// syncInvoiceRowItem, its brand/unit) the same as picking the item name would.
/** @param {any} input */
function syncInvoiceRowFromCode(input) {
  const row = input?.closest(".invoice-line-row");
  const item = data.items.find((entry) => String(entry.code || "").toLowerCase() === input.value.trim().toLowerCase());
  if (!row || !item) return;
  const itemInput = qsIn(row, ".invoice-item-input");
  itemInput.value = item.name;
  syncInvoiceRowItem(itemInput);
}

/** @param {any} input */
function syncInvoiceRowLot(input) {
  if (!input) return;
  const row = closestEl(input, ".invoice-line-row");
  const item = findItemByCodeOrName(/** @type {AnyEl | null} */ (row?.querySelector(".invoice-item-input"))?.value);
  const lot = input.value.trim();
  if (!row || !item) return;
  const branch = qsIn(row, ".invoice-source-branch-input")?.value || qs("#sourceBranch")?.value;
  // Refresh the hint for every lot edit (including clearing it back to the aggregate view) —
  // this is what the "1 available" / "No sufficient stock" mismatch needed: the hint has to
  // react to the exact lot typed, not just to the item changing.
  const stockHint = qsIn(row, "[data-role='stock-hint']");
  if (stockHint) stockHint.outerHTML = invoiceRowStockHintHtml(item, branch, lot) || `<small class="invoice-stock-hint" data-role="stock-hint"></small>`;
  if (!lot) return;
  const expiryInput = qsIn(row, ".invoice-expiry-input");
  if (!expiryInput || expiryInput.type === "hidden" || isEquipmentItem(item)) return;
  // Match the lot the way people actually type it (case/space-insensitive), preferring the
  // selected branch but falling back to any branch — a lot's expiry is the same wherever it sits.
  const sameLot = (/** @type {any} */ entry) => (entry.code === item.code || entry.item === item.name) && String(entry.lot || "").trim().toLowerCase() === lot.toLowerCase();
  const stock = data.inventory.find((entry) => sameLot(entry) && (!branch || entry.branch === branch)) || data.inventory.find(sameLot);
  if (stock) {
    expiryInput.value = stock.expiry && stock.expiry !== "N/A" ? stock.expiry : "";
    expiryInput.dataset.expiryLot = lot;
  } else if (expiryInput.dataset.expiryLot !== lot) {
    // Unknown lot: the expiry on the line belongs to the previous lot (e.g. copied from the PO),
    // so clear it and make the user enter the real one instead of silently keeping the old date.
    expiryInput.value = "";
    expiryInput.dataset.expiryLot = lot;
  }
}

/** @param {any} input @param {Record<string, any>} [options] */
function syncInvoiceRowItem(input, options = {}) {
  if (!input) return;
  const row = closestEl(input, ".invoice-line-row");
  const item = findItemByCodeOrName(input.value);
  const warehouse = qs("#sourceBranch")?.value || qsIn(row, ".invoice-source-branch-input")?.value || inventoryBranchTab || platformBranches()[0];
  // outerHTML replaces the element, so any reference captured before that point is detached —
  // re-query fresh each call instead of reusing one `stockHint` variable across both calls below.
  const refreshStockHint = (/** @type {any} */ lot) => {
    const hint = qsIn(row, "[data-role='stock-hint']");
    if (hint) hint.outerHTML = invoiceRowStockHintHtml(item, warehouse, lot) || `<small class="invoice-stock-hint" data-role="stock-hint"></small>`;
  };
  if (!item) { refreshStockHint(""); return; }
  const lotField = qsIn(row, ".lot-field");
  const lotTracked = itemStockLotTracked(item, warehouse);
  // Rebuilt for the new item/branch: the lot list (or free-text box) depends on what's in stock.
  if (lotField) {
    lotField.innerHTML = invoiceLotControlHtml(item, warehouse, "");
    const expiryInput = qsIn(row, ".invoice-expiry-input");
    if (expiryInput) expiryInput.readOnly = lotTracked;
  }
  qsIn(row, ".invoice-brand-input").value = item.brand || "";
  const codeInput = qsIn(row, ".invoice-code-input");
  if (codeInput) codeInput.value = item.code || "";
  // Skip when re-syncing a line whose unit was already set on purpose (e.g. carried over
  // from the source purchase order line, which can legitimately differ from the item's
  // default uom — a "box" PO line shouldn't get silently reset back to "piece").
  if (!options.preserveUom) qsIn(row, ".invoice-uom-input").value = normalizeUom(item.uom) || "unit";
  const expiryField = qsIn(row, ".expiry-field");
  const expiryInput = qsIn(row, ".invoice-expiry-input");
  const equipment = isEquipmentItem(item);
  expiryField?.classList.toggle("equipment-expiry-field", equipment);
  if (expiryInput && equipment) expiryInput.value = "";
  syncInvoiceRowExpiryRequired(row);
  if (!qsIn(row, ".invoice-price-input").value) qsIn(row, ".invoice-price-input").value = "";
  const stock = data.inventory
    .filter((entry) => (entry.code === item.code || entry.item === item.name) && entry.branch === warehouse && entry.qty > 0 && (hasNoExpiry(entry.expiry) || !isExpiredDate(entry.expiry)))
    .sort((a, b) => daysUntil(hasNoExpiry(a.expiry) ? "2099-12-31" : a.expiry) - daysUntil(hasNoExpiry(b.expiry) ? "2099-12-31" : b.expiry))[0];
  if (stock) {
    qsIn(row, ".invoice-lot-input").value = stock.lot || "";
    if (!equipment) qsIn(row, ".invoice-expiry-input").value = stock.expiry && stock.expiry !== "N/A" ? stock.expiry : "";
    const expiryEl = qsIn(row, ".invoice-expiry-input"); if (expiryEl) expiryEl.dataset.expiryLot = stock.lot || "";
  }
  refreshStockHint(qsIn(row, ".invoice-lot-input")?.value.trim() || "");
}

function syncInvoiceLinesForClient() {
  qsa(".invoice-item-input").forEach((input) => { if (input.value.trim()) syncInvoiceRowItem(input, { preserveUom: true }); });
  renderInvoiceComputePreview();
}

/** @param {boolean} [allowPartial] */
function syncInvoicePurchaseOrders(allowPartial = false) {
  if (!["invoice", "cancelReplace"].includes(modalType)) return;
  const clientInput = qs("#client");
  const poInput = qs("#po");
  if (!clientInput || !poInput) return;
  const client = allowPartial ? findClientByName(clientInput.value) : data.clients.find((item) => item.name.toLowerCase() === clientInput.value.trim().toLowerCase());
  if (!client) return;
  clientInput.value = client.name;
  const options = openPurchaseOrdersForClient(client.name);
  qs("#po-options").innerHTML = options.map((po) => `<option value="${escapeHtml(po.id)}">${escapeHtml(poStatus(po))}</option>`).join("");
  if (!options.some((po) => po.id === poInput.value)) poInput.value = options[0]?.id || "";
  syncInvoiceFromPurchaseOrder();
}

function syncInvoiceFromPurchaseOrder() {
  if (!["invoice", "cancelReplace"].includes(modalType)) return;
  const po = data.purchaseOrders.find((entry) => entry.id === qs("#po")?.value);
  if (!po) return;
  qs("#client").value = po.client;
  // Stock comes from the branch the order ships from (still changeable on the invoice).
  const shipsFrom = clientOrderShipsFrom(po);
  if (qs("#sourceBranch") && platformBranches().includes(shipsFrom)) qs("#sourceBranch").value = shipsFrom;
  const pendingLines = (po.lines || []).map((line) => ({ ...line, qty: poLineStatus(po, line).pending })).filter((line) => line.qty > 0);
  if (pendingLines.length) {
    qs("#invoice-line-list").innerHTML = pendingLines.map((line) => invoiceLineTemplate(line)).join("");
    qsa(".invoice-item-input").forEach((input) => syncInvoiceRowItem(input, { preserveUom: true }));
  }
  renderInvoiceComputePreview();
}

/** @returns {{ item: string, qty: number, price: number }[]} */
function collectInvoicePreviewLines() {
  return /** @type {any} */ (qsa(".invoice-line-row").map((row) => {
    const itemValue = qsIn(row, ".invoice-item-input")?.value.trim() || "";
    const qty = Number(qsIn(row, ".invoice-qty-input")?.value || 0);
    const price = Number(qsIn(row, ".invoice-price-input")?.value || 0);
    if (!itemValue || qty <= 0 || price < 0) return null;
    return { item: itemValue, qty, price };
  }).filter(Boolean));
}

function renderInvoiceComputePreview() {
  const preview = qs("#invoice-compute-preview");
  if (!preview || !["invoice", "cancelReplace"].includes(modalType)) return;
  const client = data.clients.find((entry) => entry.name === qs("#client")?.value);
  const type = qs("#type")?.value || "SI";
  const lines = collectInvoicePreviewLines();
  const gross = lines.reduce((sum, line) => sum + line.qty * line.price, 0);
  const manualDiscount = Number(qs("#discount")?.value || 0);
  const totalSalesVatInclusive = Math.max(gross - manualDiscount, 0);
  const billableTotal = type === "DR" ? 0 : totalSalesVatInclusive;
  const salesLabel = type === "SI" ? "Total Sales (VAT Inclusive)" : "Total Sales (VAT Exclusive)";
  preview.innerHTML = `<div class="preview-tax-label">${escapeHtml(type === "DR" ? "Delivery Receipt: no price posted to Sales" : "Invoice totals exclude WTax/EWT; deductions are handled in Collections payment requests.")}</div><div class="invoice-tax-summary live-preview"><div class="invoice-meta"><span>${salesLabel}</span><strong>${peso.format(billableTotal)}</strong></div><div class="invoice-meta total-line"><span>Total Amount Due</span><strong>${peso.format(billableTotal)}</strong></div></div>`;
}

// Sections a reload may land back on: the user's own modules plus the always-available pages.
// Record-detail pages aren't restorable (they need the record chosen in memory).
/** @param {string} sectionId */
function canRestoreSection(sectionId) {
  return Boolean(qs(`section.section#${CSS.escape(sectionId)}`)) && (effectiveModules().includes(sectionId) || ["notifications", "user-settings", "memos"].includes(sectionId));
}

/** @param {string} sectionId @param {Record<string, any>} [options] */
function showSection(sectionId, options = {}) {
  // The Purchase Orders page is supplier purchasing; roles that can't see supplier POs (and old
  // client-PO links) land on Sales → Sales orders, where client POs are worked.
  // Roles without supplier purchasing (e.g. Sales) keep the Purchase Orders nav item; it opens their client orders.
  if (sectionId === "purchase-orders" && currentUser && !supplierPurchasingVisible()) { salesTab = "orders"; sectionId = "sales"; }
  document.body.dataset.activeSection = sectionId;
  // Keep the URL on the current page so a browser refresh stays here instead of bouncing to the
  // dashboard. Detail pages keep whatever list page the user came from.
  if (location.protocol !== "file:" && document.body.classList.contains("app-route") && canRestoreSection(sectionId)) history.replaceState(null, "", sectionId === "dashboard" ? "/dashboard" : `/dashboard?${sectionQueryString(sectionId)}`);
  qsa(".nav-item").forEach((item) => item.classList.toggle("active", item.dataset.section === sectionId));
  qsa(".section").forEach((section) => section.classList.toggle("active", section.id === sectionId));
  const activeButton = qs(`.nav-item[data-section="${sectionId}"]`);
  qs("#page-title").textContent = activeButton?.dataset.title || sectionMeta[sectionId]?.[0] || "Dashboard";
  qs("#page-description").textContent = activeButton?.dataset.description || sectionMeta[sectionId]?.[1] || "";
  if (options.scrollTop) window.scrollTo({ top: 0, behavior: "smooth" });
  if (options.render !== false && appInitialRenderComplete) renderSection(sectionId);
  requestAnimationFrame(updateTableScrollHints);
  if (sectionId === "collections") setTimeout(renderCollectionMapVisual, 80);
  if (sectionId === "backup") renderBackup();
  if (sectionId === "logs") renderLogs();
  if (sectionId === "user-settings" && typeof loadGameBestBadge === "function") loadGameBestBadge();
}

function renderBranchFilter() {
  const current = data.branch || "all";
  qs("#branch-filter").innerHTML = [`<option value="all">All Areas</option>`, ...platformAreas().map((area) => `<option value="${escapeHtml(area)}">${escapeHtml(area)}</option>`)].join("");
  qs("#branch-filter").value = platformAreas().includes(current) ? current : "all";
  if (!platformAreas().includes(current)) data.branch = "all";
}

function applyRole() {
  if (!currentUser) {
    qs("#login-screen").classList.remove("hidden");
    return;
  }
  qs("#login-screen").classList.add("hidden");
  renderUserMenu();
  qsa(".nav-item").forEach((button) => {
    button.hidden = button.dataset.section === "security" || !effectiveModules().includes(/** @type {string} */ (button.dataset.section));
  });
  renderBranchFilter();
  if (currentUser.branch !== "all") data.branch = currentUser.branch;
  qs("#branch-filter").value = data.branch;
  qs("#branch-filter").disabled = currentUser.branch !== "all";
  const activeSection = qs(".section.active")?.id || "dashboard";
  showSection(effectiveModules().includes(activeSection) ? activeSection : "dashboard");
}

function renderUserMenu() {
  if (!currentUser) return;
  const profile = getCurrentProfile();
  qs("#welcome-name").textContent = firstName(profile.name);
  qs("#user-initials").textContent = initials(profile.name);
  qs("#user-popover-name").textContent = profile.name;
  qs("#user-popover-role").hidden = false;
  const previewOf = /** @type {string | undefined} */ (currentUser.previewOf);
  qs("#user-popover-role").textContent = previewOf ? `${profile.role} (preview · you are ${previewOf})` : profile.role || "";
  renderRolePreview(previewOf);
}

// Superadmin/CEO "Preview as role": the server lists the roles this person may preview
// (previewableRoles on /api/auth/me) and enforces the previewed role's permissions on every
// request; the client just picks one and reloads so every screen is drawn as that role.
/** @param {string | undefined} previewOf */
function renderRolePreview(previewOf) {
  const roles = /** @type {string[]} */ (currentUser?.previewableRoles || []);
  const picker = qs("#role-preview-picker");
  const banner = qs("#role-preview-banner");
  if (picker) picker.hidden = !roles.length;
  const select = /** @type {HTMLSelectElement | null} */ (qs("#role-preview-select"));
  if (select && roles.length) {
    const current = previewOf ? currentUser?.role : "";
    select.innerHTML = roles.map((role) => `<option value="${escapeHtml(role)}"${role === current ? " selected" : ""}>${escapeHtml(role)}</option>`).join("");
  }
  const startButton = qs("#role-preview-start");
  if (startButton) startButton.textContent = previewOf ? "Switch" : "Preview";
  if (banner) banner.hidden = !previewOf;
  document.body.classList.toggle("role-previewing", Boolean(previewOf));
  const name = qs("#role-preview-name");
  if (name) name.textContent = previewOf ? String(currentUser?.role || "") : "";
}

/** @param {string} role */
function switchRolePreview(role) {
  if (hasPendingSaveQueue()) return toast("Some changes are still saving. Wait until everything shows Saved, then switch.");
  MedlaneAPI.setPreviewRole(role);
  location.reload();
}

function renderUserSettings() {
  if (!currentUser) return;
  const profile = getCurrentProfile();
  qs("#settings-name").value = profile.name || "";
  qs("#settings-email").value = profile.email || "";
  qs("#settings-phone").value = profile.phone || "";
  qs("#settings-branch").value = profile.branch === "all" ? "All Areas" : profile.branch;
  qs("#settings-role").value = profile.role || "";
  qs("#settings-notes").value = profile.notes || "";
  const permissionToggle = /** @type {AnyEl} */ (qs("#settings-custom-permissions")?.closest("label, .field, .settings-row") || qs("#settings-custom-permissions"));
  if (permissionToggle) permissionToggle.hidden = true;
  qs("#settings-permissions-panel").hidden = true;
  qs("#settings-permissions-panel").innerHTML = "";
}

function renderPlatformSettings() {
  const lockedBranches = new Set(platformBranches().filter((branch) => branchUsageReasons(branch).length));
  const approvals = invoiceApprovals();
  if (qs("#approved-si")) qs("#approved-si").value = approvals.SI || "ECTOSOC";
  if (qs("#approved-ts")) qs("#approved-ts").value = approvals.TS || "ECTOSOC";
  if (qs("#approved-dr")) qs("#approved-dr").value = approvals.DR || "ECTOSOC";
  if (qs("#invoice-approval-form")) qs("#invoice-approval-form").dataset.focusRecord = "Invoice approvals";
  if (qs("#dev-settings-panel")) qs("#dev-settings-panel").hidden = !isDevEnvironment();
  qs("#platform-branch-list").innerHTML = platformBranches().map((branch) => `<div class="platform-area-chip" data-focus-record="${escapeHtml(branch)}" data-focus-text="${escapeHtml(`${branch} ${branchAddresses()[branch] || "No address set"}`)}"><span>${escapeHtml(branch)}<small>${escapeHtml(branchAddresses()[branch] || "No address set")}</small></span><button class="mini-button" type="button" data-edit-branch-address="${escapeHtml(branch)}">Address</button>${lockedBranches.has(branch) ? `<small>Used by records</small>` : `<button class="mini-button danger-button" type="button" data-remove-platform-branch="${escapeHtml(branch)}">Remove</button>`}</div>`).join("");
  renderSettingsTutorial();
}

