/** @param {string} receiptNo @param {string} status */
async function updateCollectionPaymentStatus(receiptNo, status) {
  const payments = data.payments.filter((entry) => entry.receiptNo === receiptNo || entry.paymentRequestCvNo === receiptNo);
  if (!payments.length) return toast("Collection not found.");
  if (payments.some((payment) => payment.collectionStatus === "Deposited")) return toast("This payment is already Deposited and can no longer be changed.");
  if (payments.some((payment) => payment.collectionStatus === "Bounced")) return toast("This payment bounced — a Superadmin must Redeposit it first.");
  const postedDate = status === "Posted Date" ? prompt("Posted / claim date (YYYY-MM-DD):", payments[0].postedDate || fmtDate(today)) || "" : "";
  if (!(await confirmFinalSave(`Mark ${receiptNo} as ${status}?`))) return;
  payments.forEach((payment) => {
    // The invoice's paid amount is applied as soon as the payment is posted (see approvePaymentRequest),
    // not gated on deposit confirmation. Only a bounced deposit reverses it; every other status here
    // (Deposited, Posted Date) just confirms/records the bank status without touching the balance again.
    if (status === "Bounced") reverseCollectionPayment(payment);
    else applyCollectionPayment(payment);
    payment.collectionStatus = status;
    payment.postedDate = status === "Posted Date" ? postedDate : "";
    payment.statusHistory ||= [];
    payment.statusHistory.push(...collectionStatusHistory(status));
  });
  const request = data.paymentRequests.find((entry) => entry.cvNo === (payments[0].paymentRequestCvNo || receiptNo));
  if (request) {
    request.history = paymentRequestHistory(request);
    const by = currentUser?.name || "System User";
    if (status === "Deposited") {
      request.requestStatus = "Completed";
      request.status = "Completed";
      request.completedAt = fmtDate(today);
      request.completedBy = by;
      request.history.push({ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status: "Completed", note: `Marked Deposited by ${by}.`, by });
    } else {
      request.requestStatus = "Approved";
      request.status = "Approved";
      request.history.push({ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status, note: status === "Bounced" ? `Bounced recorded by ${by}. Invoice paid amount reversed.` : `${status} recorded by ${by}.`, by });
    }
  }
  const affectedSales = [...new Map(/** @type {Sale[]} */ (payments.map((payment) => saleForPayment(payment)).filter(Boolean)).map((sale) => [sale.documentNo || sale.id, sale])).values()];
  const saveResult = await persistRecords({ payments, paymentRequests: request ? [request] : [], sales: affectedSales });
  if (!saveResult?.ok) return;
  log("Changed collection status", "Collections", `${receiptNo}: ${status}`, { save: false });
  saveData(["notifications"]);
  renderAll();
  if (payments[0].paymentRequestCvNo && document.body.dataset.activeSection === "payment-request-detail") renderPaymentRequestDetail(payments[0].paymentRequestCvNo);
  toast(`${receiptNo} marked ${status}.`);
}

// A "Multiple Cheques" collection shows one editable number per cheque; anything else one field.
/** @param {string} currentCheque @param {ChequeLine[]} [cheques] @returns {Promise<{ cheque: string, cheques: ChequeLine[] } | null>} */
function promptRedepositCheque(currentCheque, cheques = []) {
  return new Promise((resolve) => {
    const dialog = document.createElement("dialog");
    dialog.className = "modal invite-confirm-modal";
    dialog.innerHTML = `<form method="dialog"><div class="modal-header"><div><p class="eyebrow">Redeposit</p><h2>Redeposit bounced payment</h2></div><button class="icon-button" value="cancel" formnovalidate aria-label="Close">x</button></div><p class="page-description">The payment goes back to For Deposit and the invoice's paid amount is applied again. Change the cheque number if the client issued a replacement cheque.</p>${cheques.length ? cheques.map((cheque, index) => `<div class="field full"><label for="redeposit-cheque-${index}">Cheque ${index + 1} No.${cheque.chequeDate ? ` <small>(${escapeHtml(cheque.chequeDate)})</small>` : ""}</label><input id="redeposit-cheque-${index}" class="redeposit-cheque-input" autocomplete="off" value="${escapeHtml(cheque.reference || "")}" /></div>`).join("") : `<div class="field full"><label for="redeposit-cheque">Cheque No.</label><input id="redeposit-cheque" autocomplete="off" value="${escapeHtml(currentCheque)}" /></div>`}<div class="modal-actions"><button class="ghost-button" value="cancel" formnovalidate>Go Back</button><button class="primary-button confirm-button" value="confirm">Redeposit</button></div></form>`;
    document.body.appendChild(dialog);
    dialog.addEventListener("close", () => {
      const value = /** @type {HTMLInputElement | null} */ (dialog.querySelector("#redeposit-cheque"))?.value.trim() || "";
      const chequeNumbers = qsaIn(dialog, ".redeposit-cheque-input").map((input) => input.value.trim());
      dialog.remove();
      if (dialog.returnValue !== "confirm") return resolve(null);
      resolve(cheques.length ? { cheque: chequeNumbers.filter(Boolean).join(", "), cheques: cheques.map((cheque, index) => ({ ...cheque, reference: chequeNumbers[index] || cheque.reference })) } : { cheque: value, cheques: [] });
    });
    dialog.showModal();
  });
}

/** @param {string} receiptNo */
async function redepositCollectionPayment(receiptNo) {
  if (!canRedepositCollections()) return toast("Only Superadmin/CEO can redeposit a bounced payment.");
  const payments = data.payments.filter((entry) => entry.receiptNo === receiptNo || entry.paymentRequestCvNo === receiptNo);
  if (!payments.length) return toast("Collection not found.");
  if (!payments.every((payment) => payment.collectionStatus === "Bounced")) return toast("Only a Bounced payment can be redeposited.");
  const request = data.paymentRequests.find((entry) => entry.cvNo === (payments[0].paymentRequestCvNo || receiptNo));
  const previousCheque = String(request?.cheque || payments[0].reference || "");
  const previousCheques = request?.paymentType === "Multiple Cheques" && Array.isArray(request.cheques) ? request.cheques : [];
  const answer = await promptRedepositCheque(previousCheque, previousCheques);
  if (answer === null) return;
  const cheque = answer.cheque;
  const by = currentUser?.name || "System User";
  const chequeNote = cheque && cheque !== previousCheque ? ` Cheque No. changed from ${previousCheque || "-"} to ${cheque}.` : "";
  payments.forEach((payment) => {
    // Bounced reversed the invoice's paid amount — redepositing applies it again, the same as approval did.
    applyCollectionPayment(payment);
    payment.collectionStatus = "For Deposit";
    payment.postedDate = "";
    if (cheque) payment.reference = cheque;
    if (answer.cheques.length) payment.cheques = answer.cheques.map((entry) => ({ ...entry }));
    payment.statusHistory ||= [];
    payment.statusHistory.push(...collectionStatusHistory(`Redeposited — For Deposit${cheque ? ` (Cheque ${cheque})` : ""}`));
  });
  if (request) {
    if (cheque) request.cheque = cheque;
    if (answer.cheques.length) request.cheques = answer.cheques;
    request.history = paymentRequestHistory(request);
    request.history.push({ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status: "Redeposited", note: `Redeposited by ${by}; back to For Deposit and the invoice paid amount re-applied.${chequeNote}`, by });
  }
  const affectedSales = [...new Map(/** @type {Sale[]} */ (payments.map((payment) => saleForPayment(payment)).filter(Boolean)).map((sale) => [sale.documentNo || sale.id, sale])).values()];
  const saveResult = await persistRecords({ payments, paymentRequests: request ? [request] : [], sales: affectedSales });
  if (!saveResult?.ok) return;
  log("Redeposited bounced collection", "Collections", `${receiptNo}${chequeNote}`, { save: false });
  saveData(["notifications"]);
  renderAll();
  if (payments[0].paymentRequestCvNo && document.body.dataset.activeSection === "payment-request-detail") renderPaymentRequestDetail(payments[0].paymentRequestCvNo);
  toast(`${receiptNo} redeposited — now For Deposit.`);
}

function syncCollectionContactsForBalances() {
  const clientsWithBalance = new Set(data.sales.filter((sale) => Number(sale.net || 0) - Number(sale.paid || 0) > 0).map((sale) => sale.client));
  data.collectionContacts = data.clients.filter((client) => clientsWithBalance.has(client.name)).map((client) => {
    const existing = data.collectionContacts.find((contact) => contact.client === client.name) || /** @type {Record<string, any>} */ ({});
    return { client: client.name, area: client.area, status: existing.status || "Pending", lastContact: existing.lastContact || "", employee: existing.employee || "", channels: existing.channels || [], notes: existing.notes || "Open balance pending follow-up.", chequeInvoice: existing.chequeInvoice || "", weekKey: existing.weekKey || followupWeekKey() };
  });
}

/** @param {string} status */
function collectionStatusHistory(status) {
  return [{ date: new Date().toLocaleString("en-US", { month: "short", day: "numeric", year: "numeric", hour: "2-digit", minute: "2-digit", timeZone: "Asia/Manila" }), status, user: currentUser?.name || "System User" }];
}

function syncPostedCollectionReminders() {
  const todayTime = new Date(fmtDate(today)).getTime();
  data.payments.forEach((payment) => {
    if (payment.collectionStatus !== "Posted Date" || !payment.postedDate) return;
    const diffDays = Math.round((new Date(payment.postedDate).getTime() - todayTime) / 86400000);
    if (![0, 1].includes(diffDays)) return;
    const key = `${payment.receiptNo}-${payment.postedDate}-${diffDays}`;
    if (payment.postedReminderKey === key) return;
    payment.postedReminderKey = key;
    notify("Collection", `${payment.client} cheque for ${payment.receiptNo} can be claimed ${diffDays === 0 ? "today" : "tomorrow"}.`, "collections", payment.receiptNo || payment.invoice);
  });
}

