/** @param {any} [value] */
function cvYear(value = today) { return new Date(value || today).getFullYear(); }
/** @param {any} [year] */
function nextCvNumber(year = cvYear()) {
  const next = (data.paymentRequests || []).filter((request) => cvYear(request.date || request.createdAt) === Number(year)).reduce((max, request) => Math.max(max, Number(String(request.cvNo || "").replace(/\D/g, "")) || 0), 0) + 1;
  return `CV${String(next).padStart(6, "0")}`;
}
const paymentRequestInstructions = "INSTRUCTIONS : This form must be accomplished in duplicate. All supporting documents must be attached with receipts issued to Medlane Diagnostics Solutions Inc. Incomplete information will delay processing of this payment request or no attached receipts will not receive any payment.";
/** @param {string} clientName */
function paymentRequestInvoiceDatalistOptions(clientName) {
  return openInvoicesForPaymentRequest(clientName).map((sale) => `<option value="${escapeHtml(sale.documentNo || sale.id)}"></option>`).join("");
}

/** @param {string} clientName @param {string} invoice */
function paymentRequestRowBalance(clientName, invoice) {
  const sale = invoice ? openInvoicesForPaymentRequest(clientName).find((entry) => (entry.documentNo || entry.id) === invoice) : null;
  return sale ? Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0) : 0;
}

/** @param {Record<string, any>} [line] */
function paymentRequestLineTemplate(line = {}) {
  const clientName = qs("#employee")?.value.trim() || "";
  const payee = findClientByName(clientName);
  const wtaxDefault = line.withholdingTax != null ? line.withholdingTax : Boolean(payee?.withholdingTax);
  const ewtDefault = line.expandedWithholdingTax != null ? line.expandedWithholdingTax : Boolean(payee?.expandedWithholdingTax);
  const rowId = `pr-row-${++paymentRequestRowUid}`;
  const amountDue = line.amountDue != null ? line.amountDue : paymentRequestRowBalance(clientName, line.invoice || "");
  const amountPaid = line.amount != null ? line.amount : amountDue;
  const balance = Math.max(amountDue - amountPaid, 0);
  return `<div class="payment-request-line-row payment-request-invoice-row"><div class="field"><label>Invoice</label><input class="payment-request-invoice-input" name="${rowId}" list="${rowId}-options" autocomplete="off" value="${escapeHtml(line.invoice || "")}" placeholder="Type or pick invoice" /><datalist id="${rowId}-options">${paymentRequestInvoiceDatalistOptions(clientName)}</datalist></div><div class="field"><label>Amount Due</label><input class="payment-request-amount-due" readonly value="${amountDue ? amountDue.toFixed(2) : "0.00"}" /></div><div class="field"><label>Amount Paid</label><input class="payment-request-amount" type="number" min="0" step="0.01" value="${amountPaid || ""}" /></div><div class="field"><label>Balance</label><input class="payment-request-balance" readonly value="${balance.toFixed(2)}" /></div><div class="payment-request-row-withholding"><label class="ios-check-row compact-doc-check"><input class="payment-request-row-wtax" type="checkbox" ${wtaxDefault ? "checked" : ""} /><span></span><strong>WTax 5%</strong></label><label class="ios-check-row compact-doc-check"><input class="payment-request-row-ewt" type="checkbox" ${ewtDefault ? "checked" : ""} /><span></span><strong>EWT 1%</strong></label></div><button class="icon-button danger-button remove-payment-request-line" type="button" aria-label="Remove item">Remove</button></div>`;
}

/** @param {any} row @param {{ invoiceChanged?: any }} options */
function syncPaymentRequestRowDerived(row, { invoiceChanged = false } = {}) {
  const clientName = qs("#employee")?.value.trim() || "";
  const invoice = qsIn(row, ".payment-request-invoice-input")?.value.trim() || "";
  const amountDue = paymentRequestRowBalance(clientName, invoice);
  const amountDueInput = qsIn(row, ".payment-request-amount-due");
  if (amountDueInput) amountDueInput.value = amountDue.toFixed(2);
  const amountInput = qsIn(row, ".payment-request-amount");
  if (invoiceChanged && amountInput) amountInput.value = amountDue || "";
  const withholdingTax = Boolean(qsIn(row, ".payment-request-row-wtax")?.checked);
  const expandedWithholdingTax = Boolean(qsIn(row, ".payment-request-row-ewt")?.checked);
  const deductions = paymentRequestRowDeductions({ amountDue, amount: 0, withholdingTax, expandedWithholdingTax });
  const balanceInput = qsIn(row, ".payment-request-balance");
  if (balanceInput) balanceInput.value = Math.max(amountDue - Number(amountInput?.value || 0) - deductions.withholdingTax - deductions.expandedWithholdingTax, 0).toFixed(2);
}
/** @param {any[]} [lines] @param {string | null} [preselectDoc] */
function renderPaymentRequestEditor(lines = [{}], preselectDoc = null) {
  paymentRequestPreselectedInvoice = preselectDoc || null;
  if (paymentRequestPreselectedInvoice) {
    const sale = data.sales.find((entry) => (entry.documentNo || entry.id) === paymentRequestPreselectedInvoice);
    const balance = sale ? Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0) : 0;
    return `<div class="field full payment-request-editor"><label>Invoice</label><input value="${escapeHtml(`${paymentRequestPreselectedInvoice} — ${peso.format(balance)} balance`)}" readonly /><div class="field"><label for="single-amount">Amount</label><input id="single-amount" class="payment-request-single-amount" type="number" min="0" step="0.01" required /></div><label class="ios-check-row"><input id="withholdingTax" name="withholdingTax" type="checkbox" value="true" /><span></span><strong>Eligible for WTax 5%</strong></label><label class="ios-check-row"><input id="expandedWithholdingTax" name="expandedWithholdingTax" type="checkbox" value="true" /><span></span><strong>Eligible for EWT 1%</strong></label><div class="field payment-request-total-field"><label for="total">Total</label><input id="total" name="total" readonly value="0.00" /></div><div id="payment-request-tax-preview" class="invoice-compute-preview payment-deduction-preview"></div><div class="payment-request-fixed-instructions"><strong>Instructions</strong><p>${escapeHtml(paymentRequestInstructions)}</p></div></div>`;
  }
  return `<div class="field full payment-request-editor"><div class="field payment-request-net-amount-field"><label for="netAmount">Net Amount</label><p class="field-help">Enter the total net amount this collection should cover, then add the invoice(s) it pays for below.</p><input id="netAmount" name="netAmount" type="number" min="0" step="0.01" required /></div><label>Invoices and Amount</label><div id="payment-request-line-list">${lines.map((line) => paymentRequestLineTemplate(line)).join("")}</div><div class="payment-request-editor-actions"><button class="ghost-button" id="add-payment-request-line" type="button">Add Item</button><div class="field payment-request-total-field"><label for="total">Total</label><input id="total" name="total" readonly value="0.00" /></div></div><div id="payment-request-tax-preview" class="payment-request-row-previews"></div><div class="payment-request-fixed-instructions"><strong>Instructions</strong><p>${escapeHtml(paymentRequestInstructions)}</p></div></div>`;
}
function collectPaymentRequestLines() {
  const clientName = qs("#employee")?.value.trim() || "";
  return qsa(".payment-request-invoice-row").map((row) => {
    const invoice = qsIn(row, ".payment-request-invoice-input")?.value.trim() || "";
    const amountDue = paymentRequestRowBalance(clientName, invoice);
    const amount = Number(qsIn(row, ".payment-request-amount")?.value || 0);
    const withholdingTax = Boolean(qsIn(row, ".payment-request-row-wtax")?.checked);
    const expandedWithholdingTax = Boolean(qsIn(row, ".payment-request-row-ewt")?.checked);
    const deductions = paymentRequestRowDeductions({ amountDue, amount, withholdingTax, expandedWithholdingTax });
    return {
      invoice, amountDue, amount,
      balance: Math.max(amountDue - amount - deductions.withholdingTax - deductions.expandedWithholdingTax, 0),
      withholdingTax, expandedWithholdingTax,
    };
  }).filter((line) => line.invoice || line.amount);
}
/** @param {any} rows @param {any} netAmount */
function paymentRequestNetAmountExceeded(rows, netAmount) {
  return netAmount > 0 && rows.reduce((/** @type {number} */ sum, /** @type {any} */ row) => sum + Number(row.amount || 0), 0) > netAmount;
}

const EXPENSE_CLASSIFICATION_OPTIONS = ["Accommodation", "Advertising & Marketing", "Bidding Expenses", "Delivery Fee", "Fixed Assets", "Freight/Importation", "Per Diem"];

/** @param {Record<string, any>} [line] @param {Record<string, any>} [options] */
function financialLineTemplate(line = {}, options = {}) {
  const uid = ++paymentRequestRowUid;
  const vendorField = options.vendor === false ? "" : `<div class="field"><label>Vendor</label><input class="payment-request-vendor" name="financial-vendor-${uid}" list="financial-vendor-options" autocomplete="off" value="${escapeHtml(line.vendor || "")}" /></div>`;
  const classificationField = options.classification ? `<div class="field"><label>Classification</label><input class="payment-request-classification" name="financial-classification-${uid}" list="expense-classification-options" value="${escapeHtml(line.classification || "")}" autocomplete="off" required /></div>` : "";
  const rowClass = options.classification ? "payment-request-line-row financial-line-row financial-line-row-expense" : "payment-request-line-row financial-line-row";
  return `<div class="${rowClass}">${vendorField}<div class="field"><label>Particulars</label><input class="payment-request-particulars" value="${escapeHtml(line.particulars || "")}" required /></div>${classificationField}<div class="field"><label>Amount</label><input class="payment-request-amount" type="number" min="0" step="0.01" value="${line.amount || ""}" required /></div><button class="icon-button danger-button remove-payment-request-line" type="button" aria-label="Remove item">Remove</button></div>`;
}

/** @param {any[]} [lines] */
function renderFinancialRequestEditor(lines = [{}]) {
  const vendorOptions = [...new Set(activeSuppliers().map((s) => s.name))].map((name) => `<option value="${escapeHtml(name)}"></option>`).join("");
  const lineOptions = { vendor: modalType !== "payable", classification: modalType === "replenishment" };
  const classificationDatalist = lineOptions.classification ? `<datalist id="expense-classification-options">${EXPENSE_CLASSIFICATION_OPTIONS.map((option) => `<option value="${escapeHtml(option)}"></option>`).join("")}</datalist>` : "";
  return `<div class="field full payment-request-editor"><label>Itemized Particulars</label><datalist id="financial-vendor-options">${vendorOptions}</datalist>${classificationDatalist}<div id="payment-request-line-list">${lines.map((line) => financialLineTemplate(line, lineOptions)).join("")}</div><div class="payment-request-editor-actions"><button class="ghost-button" id="add-payment-request-line" type="button">Add Item</button><div class="field payment-request-total-field"><label for="amount">Net Total</label><input id="amount" name="amount" readonly value="0.00" /></div></div><div id="financial-request-tax-preview" class="invoice-compute-preview payment-deduction-preview"></div></div>`;
}

/** @param {any} input */
function enforceExpenseClassification(input) {
  const value = input.value.trim();
  if (value && !EXPENSE_CLASSIFICATION_OPTIONS.includes(value)) {
    toast("Select a classification from the list — custom entries aren't allowed.");
    input.value = "";
  }
}

/** @returns {any[]} */
function collectFinancialLines() {
  return qsa(".financial-line-row").map((row) => {
    /** @type {Record<string, any>} */
    const line = {
      vendor: qsIn(row, ".payment-request-vendor")?.value.trim() || "",
      particulars: qsIn(row, ".payment-request-particulars")?.value.trim() || "",
      amount: Number(qsIn(row, ".payment-request-amount")?.value || 0),
    };
    const classificationInput = qsIn(row, ".payment-request-classification");
    if (classificationInput) {
      const value = classificationInput.value.trim();
      line.classification = EXPENSE_CLASSIFICATION_OPTIONS.includes(value) ? value : "";
    }
    return line;
  }).filter((line) => line.vendor || line.particulars || line.amount);
}

function syncFinancialRequestTotal() {
  if (!["payable", "replenishment"].includes(modalType)) return;
  const gross = collectFinancialLines().reduce((sum, line) => sum + Number(line.amount || 0), 0);
  const taxBase = withholdingTaxBase(gross);
  const withholdingTax1 = modalType === "payable" && qs("#withholdingTax1")?.checked ? roundMoney(taxBase * 0.01) : 0;
  const withholdingTax2 = modalType === "payable" && qs("#withholdingTax2")?.checked ? roundMoney(taxBase * 0.02) : 0;
  const total = Math.max(gross - withholdingTax1 - withholdingTax2, 0);
  if (qs("#amount")) qs("#amount").value = total.toFixed(2);
  const preview = qs("#financial-request-tax-preview");
  if (preview) preview.innerHTML = modalType === "payable" ? `<div class="preview-tax-label">Optional withholding deductions computed from VAT-exclusive base</div><div class="invoice-tax-summary live-preview"><div class="invoice-meta"><span>Gross Payable</span><strong>${peso.format(gross)}</strong></div><div class="invoice-meta"><span>VAT-exclusive Base</span><strong>${withholdingMoney(taxBase)}</strong></div><div class="invoice-meta"><span>Withholding 1%</span><strong>${withholdingMoney(withholdingTax1)}</strong></div><div class="invoice-meta"><span>Withholding 2%</span><strong>${withholdingMoney(withholdingTax2)}</strong></div><div class="invoice-meta total-line"><span>Net Payable</span><strong>${peso.format(total)}</strong></div></div>` : "";
}

/** @param {any} value */
function roundMoney(value) { return Math.round(Number(value || 0) * 100) / 100; }
/** @param {any} value */
function withholdingMoney(value) { return Number(value || 0).toLocaleString("en-PH", { style: "currency", currency: "PHP", minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
/** @param {number} gross */
function withholdingTaxBase(gross) { return roundMoney(Number(gross || 0) / 1.12); }

/** @param {number} gross */
function financialRequestDeductions(gross) {
  const taxBase = withholdingTaxBase(gross);
  const withholdingTax1 = modalType === "payable" && qs("#withholdingTax1")?.checked ? roundMoney(taxBase * 0.01) : 0;
  const withholdingTax2 = modalType === "payable" && qs("#withholdingTax2")?.checked ? roundMoney(taxBase * 0.02) : 0;
  return { grossAmount: gross, withholdingTax1, withholdingTax2, total: Math.max(gross - withholdingTax1 - withholdingTax2, 0) };
}
/** @param {number} gross */
function paymentRequestDeductions(gross) {
  const taxBase = withholdingTaxBase(gross);
  const withholdingTax = qs("#withholdingTax")?.checked ? roundMoney(taxBase * 0.05) : 0;
  const expandedWithholdingTax = qs("#expandedWithholdingTax")?.checked ? roundMoney(taxBase * 0.01) : 0;
  return { withholdingTax, expandedWithholdingTax, total: Math.max(gross - withholdingTax - expandedWithholdingTax, 0) };
}

function togglePaymentRequestChequeFields() {
  const type = qs("#paymentType")?.value;
  syncPaymentRequestBankAccount();
  ["bank", "bankAccount", "cheque", "chequeDate", "transferDate"].forEach((id) => {
    const field = /** @type {AnyEl} */ (qs(`#${id}`)?.closest(".field"));
    if (!field) return;
    const visible = id === "bank" ? ["Check", "Multiple Cheques", "Bank Transfer"].includes(type) : id === "bankAccount" || id === "transferDate" ? type === "Bank Transfer" : type === "Check";
    field.hidden = !visible;
    qs(`#${id}`).required = (["Check", "Multiple Cheques"].includes(type) && id === "bank") || (type === "Bank Transfer" && ["bank", "transferDate"].includes(id));
    if (!visible && id !== "bankAccount") qs(`#${id}`).value = "";
  });
  ensureMultiChequeEditor();
  const editor = qs("#multi-cheque-editor");
  if (editor) {
    const multi = type === "Multiple Cheques";
    editor.hidden = !multi;
    qsaIn(editor, ".multi-cheque-number, .multi-cheque-date").forEach((input) => { input.required = multi; });
  }
}

/** @param {Partial<ChequeLine>} [cheque] */
function multiChequeRowTemplate(cheque = {}) {
  return `<div class="payment-request-line-row multi-cheque-row"><div class="field"><label>Cheque No.</label><input class="multi-cheque-number" autocomplete="off" value="${escapeHtml(cheque.reference || "")}" /></div><div class="field"><label>Cheque Date</label><input class="multi-cheque-date" type="date" value="${escapeHtml(cheque.chequeDate || "")}" /></div><button class="icon-button danger-button remove-multi-cheque" type="button" aria-label="Remove cheque">Remove</button></div>`;
}

// The Multiple Cheques editor lives right after the single Cheque Date field and is only shown
// when Type of Payment = "Multiple Cheques".
function ensureMultiChequeEditor() {
  if (qs("#multi-cheque-editor")) return;
  const anchor = qs("#chequeDate")?.closest(".field");
  if (!anchor) return;
  anchor.insertAdjacentHTML("afterend", `<div class="field full" id="multi-cheque-editor" hidden><label>Cheques</label><p class="field-help">Add one row per cheque received for this collection.</p><div id="multi-cheque-list">${multiChequeRowTemplate()}${multiChequeRowTemplate()}</div><div class="payment-request-editor-actions"><button class="ghost-button" id="add-multi-cheque" type="button">Add Cheque</button></div></div>`);
}

/** @returns {ChequeLine[]} */
function collectMultiCheques() {
  return qsa(".multi-cheque-row").map((row) => ({
    reference: qsIn(row, ".multi-cheque-number")?.value.trim() || "",
    chequeDate: qsIn(row, ".multi-cheque-date")?.value || "",
  })).filter((cheque) => cheque.reference || cheque.chequeDate);
}

function syncPaymentRequestBankAccount() {
  const bank = data.banks.find((entry) => entry.name === qs("#bank")?.value);
  if (qs("#bankAccount")) qs("#bankAccount").value = bank?.account || "";
}

function syncPaymentRequestDeductionDefaults() {
  const payee = findClientByName(qs("#employee")?.value || "");
  if (qs("#withholdingTax")) qs("#withholdingTax").checked = Boolean(payee?.withholdingTax);
  if (qs("#expandedWithholdingTax")) qs("#expandedWithholdingTax").checked = Boolean(payee?.expandedWithholdingTax);
}
/** @param {any} row */
function paymentRequestRowDeductions(row) {
  // Withholding tax is computed off the invoice's gross amount due, not the cash amount being
  // collected — the client withholds tax and remits it to BIR on the invoice's full value, so
  // the invoice is credited for cash received PLUS the withheld tax credit (not cash minus tax,
  // which double-counts the withholding and leaves the invoice looking under-settled).
  const taxBase = withholdingTaxBase(Number(row.amountDue ?? row.amount ?? 0));
  const withholdingTax = row.withholdingTax ? roundMoney(taxBase * 0.05) : 0;
  const expandedWithholdingTax = row.expandedWithholdingTax ? roundMoney(taxBase * 0.01) : 0;
  return { taxBase, withholdingTax, expandedWithholdingTax, total: roundMoney(Number(row.amount || 0) + withholdingTax + expandedWithholdingTax) };
}

function syncPaymentRequestTotal() {
  if (paymentRequestPreselectedInvoice) {
    const gross = Number(qs("#single-amount")?.value || 0);
    const deductions = paymentRequestDeductions(gross);
    if (qs("#total")) qs("#total").value = deductions.total.toFixed(2);
    const preview = qs("#payment-request-tax-preview");
    if (preview) preview.innerHTML = `<div class="preview-tax-label">WTax/EWT computed from VAT-exclusive base</div><div class="invoice-tax-summary live-preview"><div class="invoice-meta"><span>Gross Request</span><strong>${peso.format(gross)}</strong></div><div class="invoice-meta"><span>VAT-exclusive Base</span><strong>${withholdingMoney(withholdingTaxBase(gross))}</strong></div><div class="invoice-meta"><span>Withholding Tax 5%</span><strong>${withholdingMoney(deductions.withholdingTax)}</strong></div><div class="invoice-meta"><span>Expanded Withholding Tax 1%</span><strong>${withholdingMoney(deductions.expandedWithholdingTax)}</strong></div><div class="invoice-meta total-line"><span>Total Payment Received</span><strong>${peso.format(deductions.total)}</strong></div></div>`;
    return;
  }
  const rows = collectPaymentRequestLines();
  const netAmount = Number(qs("#netAmount")?.value || 0);
  const sumAmounts = rows.reduce((sum, row) => sum + Number(row.amount || 0), 0);
  let grandTotal = 0;
  const blocks = rows.filter((row) => row.invoice || row.amount).map((row) => {
    const deductions = paymentRequestRowDeductions(row);
    // "Total" must tally with the Net Amount entered above (both represent cash being
    // collected) — deductions.total is the invoice-settlement value (cash + withholding
    // credit) used for AR-crediting on approval, not for this cash-reconciliation total.
    grandTotal += Number(row.amount || 0);
    return `<div class="invoice-tax-summary live-preview payment-request-row-breakdown"><div class="preview-tax-label">${escapeHtml(row.invoice || "Unselected invoice")}</div><div class="invoice-meta"><span>Amount</span><strong>${peso.format(row.amount)}</strong></div><div class="invoice-meta"><span>VAT-exclusive Base</span><strong>${withholdingMoney(deductions.taxBase)}</strong></div>${deductions.withholdingTax ? `<div class="invoice-meta"><span>Withholding Tax 5%</span><strong>${withholdingMoney(deductions.withholdingTax)}</strong></div>` : ""}${deductions.expandedWithholdingTax ? `<div class="invoice-meta"><span>Expanded Withholding Tax 1%</span><strong>${withholdingMoney(deductions.expandedWithholdingTax)}</strong></div>` : ""}<div class="invoice-meta total-line"><span>Net For This Invoice</span><strong>${peso.format(deductions.total)}</strong></div></div>`;
  }).join("");
  if (qs("#total")) qs("#total").value = grandTotal.toFixed(2);
  const overLimit = paymentRequestNetAmountExceeded(rows, netAmount);
  qs("#netAmount")?.closest(".field")?.classList.toggle("field-error", overLimit);
  const preview = qs("#payment-request-tax-preview");
  if (preview) preview.innerHTML = `${blocks}${overLimit ? `<p class="field-error-message">Itemized amount total (${peso.format(sumAmounts)}) exceeds Net Amount (${peso.format(netAmount)}). Reduce the amounts or increase Net Amount.</p>` : ""}`;
}
/** @param {any} request */
function paymentRequestHtml(request) {
  const items = request.items?.length ? request.items : [{ particulars: request.particulars || "", amount: request.amount || request.total || 0 }];
  const paymentDate = request.paymentType === "Bank Transfer" ? request.transferDate : request.chequeDate;
  return `<section class="payment-request-print">${printableBrandHeaderHtml(request.cvNo)}<div class="pr-meta"><span>Client: <strong>${escapeHtml(request.employee)}</strong></span><span>Collector: <strong>${escapeHtml(request.preparedBy)}</strong></span><span>Date: <strong>${escapeHtml(request.date)}</strong></span></div><div class="pr-checks"><strong>Mode of Payment:</strong><span>${request.paymentType === "Cash" ? "[x]" : "[ ]"} Cash</span><span>${request.paymentType === "Check" ? "[x]" : "[ ]"} Check</span><span>${request.paymentType === "Multiple Cheques" ? "[x]" : "[ ]"} Multiple Cheques</span><span>${request.paymentType === "Bank Transfer" ? "[x]" : "[ ]"} Bank Transfer</span><span>${request.paymentType === "Debit Memo" ? "[x]" : "[ ]"} Debit Memo</span></div><table><thead><tr><th>Date</th><th>Particulars</th><th>Amount</th></tr></thead><tbody>${items.map((/** @type {any} */ item, /** @type {any} */ index) => `<tr><td>${index === 0 ? escapeHtml(request.date) : ""}</td><td>${escapeHtml(item.particulars)}</td><td>${peso.format(item.amount)}</td></tr>`).join("")}${request.withholdingTax ? `<tr><td colspan="2">Less: Withholding Tax 5%</td><td>${withholdingMoney(request.withholdingTax)}</td></tr>` : ""}${request.expandedWithholdingTax ? `<tr><td colspan="2">Less: Expanded Withholding Tax 1%</td><td>${withholdingMoney(request.expandedWithholdingTax)}</td></tr>` : ""}<tr><td colspan="2"><strong>Total</strong></td><td><strong>${peso.format(request.total)}</strong></td></tr></tbody></table><p class="pr-instructions"><strong>${escapeHtml(paymentRequestInstructions)}</strong></p><footer><div>Prepared by:<br><strong>${escapeHtml(request.preparedBy)}</strong><br>${escapeHtml(request.preparedRole)}</div><div>Approved by:<br><strong>Maria Emma F. Llorin</strong><br>CEO</div><div><strong>PAYMENT DETAILS:</strong><br>Bank Name: ${escapeHtml(request.bank || "-")}<br>Account No.: ${escapeHtml(request.bankAccount || "-")}<br>${request.paymentType === "Multiple Cheques" && request.cheques?.length ? request.cheques.map((/** @type {ChequeLine} */ cheque, /** @type {number} */ index) => `Check ${index + 1}: ${escapeHtml(cheque.reference || "-")} · ${escapeHtml(cheque.chequeDate || "-")}`).join("<br>") : `Check no: ${escapeHtml(request.cheque || "-")}<br>Date: ${escapeHtml(paymentDate || "-")}`}<br>Name and Signature of approver:</div></footer>${printableFooterHtml()}</section>`;
}
/** @param {any} identifier */
async function previewPaymentRequest(identifier) {
  const request = typeof identifier === "number" ? data.paymentRequests[identifier] : data.paymentRequests.find((item) => item.cvNo === identifier || item.id === identifier);
  const id = request?.cvNo || request?.id || identifier;
  if (!id) return toast("Payment request not found.");
  showPaymentRequestPreviewLoading();
  const printable = await MedlaneAPI.printablePaymentRequest(id).catch((error) => { toast(error.message || "Unable to load payment request."); qs("#payment-request-preview-modal").close(); return null; });
  if (!printable) return;
  qs("#payment-request-preview-title").textContent = printable.title;
  qs("#payment-request-preview-content").innerHTML = sanitizeHtml(printable.html);
}

/** @param {string} id */
async function printTransferRequest(id) {
  showPaymentRequestPreviewLoading();
  const printable = await MedlaneAPI.printableTransfer(id).catch((error) => { toast(error.message || "Unable to load transfer request."); qs("#payment-request-preview-modal").close(); return null; });
  if (!printable) return;
  qs("#payment-request-preview-title").textContent = printable.title;
  qs("#payment-request-preview-content").innerHTML = sanitizeHtml(printable.html);
}

function renderCollectionContactMap() {
  renderCollectionMapVisual();
  const grouped = Object.entries(data.collectionContacts.reduce((/** @type {Record<string, any>} */ acc, contact) => { acc[contact.area] ||= []; acc[contact.area].push(contact); return acc; }, {}));
  qs("#collection-map-actions").innerHTML = grouped.map(([area, contacts], index) => `<details class="region-contact-group" ${index === 0 ? "open" : ""} data-focus-text="${escapeHtml(area)}"><summary><strong>${escapeHtml(area)}</strong><span>${contacts.length} client${contacts.length === 1 ? "" : "s"}</span></summary><div class="region-client-list">${contacts.map((/** @type {CollectionContact} */ contact) => `<details class="contact-action-card ${contactStatusClass(contact.status)}" data-focus-text="${escapeHtml(contact.client)} ${escapeHtml(contact.area)} ${escapeHtml(contact.status)}"><summary><div><strong>${escapeHtml(contact.client)}</strong><small>${escapeHtml(contact.lastContact || "Not contacted")} · ${escapeHtml(contact.employee || "Unassigned")}</small></div><span class="contact-status-badge ${contactStatusClass(contact.status)}">${escapeHtml(contactStatusLabel(contact.status))}</span></summary><p>${escapeHtml(contact.notes)}</p><div class="contact-control-group"><small>Channels used (select one or more)</small><div class="channel-buttons"><label class="channel-check ${contact.channels.includes("Call") ? "active" : ""}"><input type="checkbox" data-contact-channel="Call" data-contact-client="${escapeHtml(contact.client)}" ${contact.channels.includes("Call") ? "checked" : ""} /><span>☎</span>Call</label><label class="channel-check ${contact.channels.includes("Email") ? "active" : ""}"><input type="checkbox" data-contact-channel="Email" data-contact-client="${escapeHtml(contact.client)}" ${contact.channels.includes("Email") ? "checked" : ""} /><span>@</span>Email</label><label class="channel-check ${contact.channels.includes("Telephone") ? "active" : ""}"><input type="checkbox" data-contact-channel="Telephone" data-contact-client="${escapeHtml(contact.client)}" ${contact.channels.includes("Telephone") ? "checked" : ""} /><span>☎</span>Telephone</label></div></div><div class="contact-control-group"><small>Outcome</small><div class="contact-buttons"><button class="mini-button ${contact.status === "Answered" ? "active" : ""}" data-contact-status="Answered" data-contact-client="${escapeHtml(contact.client)}">Answered</button><button class="mini-button ${contact.status === "Unreached" ? "active" : ""}" data-contact-status="Unreached" data-contact-client="${escapeHtml(contact.client)}">Unreached</button><button class="mini-button ${contact.status === "No Response" ? "active" : ""}" data-contact-status="No Response" data-contact-client="${escapeHtml(contact.client)}">No Reply</button></div></div></details>`).join("")}</div></details>`).join("");
  qs("#collection-map-actions").innerHTML = grouped.map(([area, contacts], index) => `<details class="region-contact-group" ${index === 0 ? "open" : ""} data-focus-text="${escapeHtml(area)}"><summary><strong>${escapeHtml(area)}</strong><span>${contacts.length} client${contacts.length === 1 ? "" : "s"}</span></summary><div class="region-client-list">${contacts.map((/** @type {CollectionContact} */ contact) => contactActionCard(contact)).join("")}</div></details>`).join("") || `<article class="panel"><p>No clients with unpaid invoice balances need follow-up.</p></article>`;
  table("#collection-contact-history", ["Date", "Client", "Area", "Invoice", "Channel", "Status", "Employee", "Notes"], data.collectionContactHistory.map((/** @type {any} */ item) => [item.date, item.client || item.area, item.area, item.invoice || "-", item.channels || "-", `<span class="pill ${statusClass(["Answered", "Cheque Available"].includes(item.status) ? "Paid" : item.status === "No Response" ? "Overdue" : "Near Due")}">${contactStatusLabel(item.status)}</span>`, item.employee, item.notes]));
}

/** @param {CollectionContact} contact */
function contactActionCard(contact) {
  const channels = contact.channels || [];
  const pendingInvoices = data.sales.filter((sale) => sale.client === contact.client && Number(sale.net || 0) - Number(sale.paid || 0) > 0);
  const invoiceList = `<details class="pending-invoice-list"><summary>Pending invoices (${pendingInvoices.length})</summary>${pendingInvoices.map((sale) => `<div><strong>${escapeHtml(sale.documentNo || sale.id)}</strong><span>${peso.format(Math.max(Number(sale.net || 0) - Number(sale.paid || 0), 0))}</span><small>Due ${fmtDate(addDays(sale.date, sale.terms))}</small></div>`).join("") || `<p>No unpaid invoices.</p>`}</details>`;
  const channelButton = (/** @type {any} */ channel, /** @type {any} */ icon) => `<label class="channel-check ${channels.includes(channel) ? "active" : ""}"><input type="checkbox" data-contact-channel="${channel}" data-contact-client="${escapeHtml(contact.client)}" ${channels.includes(channel) ? "checked" : ""} /><span>${icon}</span>${channel}</label>`;
  const statusButton = (/** @type {any} */ status, /** @type {any} */ label, tone = "") => `<button class="mini-button ${tone} ${contact.status === contactStatusFromLabel(status) ? "active" : ""}" data-contact-status="${escapeHtml(status)}" data-contact-client="${escapeHtml(contact.client)}">${escapeHtml(label)}</button>`;
  const chequeNote = contact.status === "Cheque Available" && contact.chequeInvoice ? `<div class="contact-control-group cheque-invoice-note"><small>Cheque invoice</small><strong>${escapeHtml(contact.chequeInvoice)}</strong></div>` : "";
  return `<details class="contact-action-card ${contactStatusClass(contact.status)}" data-focus-record="${escapeHtml(contact.client || contact.area)}" data-focus-text="${escapeHtml(contact.client)} ${escapeHtml(contact.area)} ${escapeHtml(contact.status)}"><summary><div><strong>${escapeHtml(contact.client)}</strong><small>${escapeHtml(contact.lastContact || "Not contacted")} · ${escapeHtml(contact.employee || "Unassigned")}</small></div><span class="contact-status-badge ${contactStatusClass(contact.status)}">${escapeHtml(contactStatusLabel(contact.status))}</span></summary><p>${escapeHtml(contact.notes)}</p>${chequeNote}${invoiceList}<div class="contact-control-group"><small>Channels used (select one or more)</small><div class="channel-buttons">${channelButton("Call", "☎")}${channelButton("Email", "@")}${channelButton("Telephone", "☎")}</div></div><div class="contact-control-group"><small>Outcome</small><div class="contact-buttons">${statusButton("Answered", "Answered")}${statusButton("Unreached", "Unreached")}${statusButton("No Reply", "No Reply", "danger-button")}${statusButton("Cheque Available", "Cheque Available")}</div></div></details>`;
}

function collectionContactsGeoJson() {
  return { type: "FeatureCollection", features: data.collectionContacts.map((contact) => {
    const coords = clientCoordinates[contact.client] || [12.8797, 121.7740];
    return { type: "Feature", properties: contact, geometry: { type: "Point", coordinates: [coords[1], coords[0]] } };
  }) };
}

function collectionRegionSummaries() {
  return Object.entries(data.collectionContacts.reduce((/** @type {Record<string, any>} */ acc, contact) => { acc[contact.area] ||= []; acc[contact.area].push(contact); return acc; }, {})).map(([area, contacts]) => {
    const coords = /** @type {any[]} */ (contacts.map((/** @type {CollectionContact} */ contact) => clientCoordinates[contact.client]).filter(Boolean));
    const lat = coords.length ? coords.reduce((sum, item) => sum + item[0], 0) / coords.length : 12.8797;
    const lng = coords.length ? coords.reduce((sum, item) => sum + item[1], 0) / coords.length : 121.7740;
    const chequeReady = contacts.filter((/** @type {CollectionContact} */ contact) => contact.status === "Cheque Available").length;
    const noReply = contacts.filter((/** @type {CollectionContact} */ contact) => contact.status === "No Response").length;
    const answered = contacts.filter((/** @type {CollectionContact} */ contact) => contact.status === "Answered").length;
    const status = chequeReady ? "Cheque Available" : noReply ? "No Response" : answered === contacts.length ? "Answered" : contacts.some((/** @type {CollectionContact} */ contact) => contact.status === "Unreached") ? "Unreached" : "Pending";
    return { area, contacts, lat, lng, status };
  });
}

